window.OSAP_FT=window.OSAP_FT||{};window.OSAP_FT["02"]={"https://www.gov.uk/foreign-travel-advice/azerbaijan":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"c2a4809c0984d708d5fa34409f695dff62e69005323e584f682afaf4e15cec0b","read":"https://www.gov.uk/api/content/foreign-travel-advice/azerbaijan","bytes":81907,"x":"fulltext v1","title":"Azerbaijan travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-27T00:00:00+00:00","mod":"2026-10-23T13:44:51+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["Your travel insurance could be invalidated if you travel against advice from the Foreign, Commonwealth & Development Office (FCDO)."]},{"k":"h","s":["Areas where FCDO advises against travel"]},{"k":"hs","s":["Azerbaijan-Armenia border"]},{"k":"p","s":["The border with Armenia remains closed. The FCDO advises against all travel to within 5km of the border with Armenia, due to tensions between Azerbaijan and Armenia. Note that this does not include the border of Azerbaijan’s Nakhchivan exclave with Armenia."]},{"k":"h","s":["Areas where FCDO advises against all but essential travel"]},{"k":"hs","s":["South-western Azerbaijan (those regions affected by conflict in 2020 and 2023)"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) advises against all but essential travel to:"]},{"k":"li","s":["The districts (‘rayons’) of Kelbajar, Lachin, Qubadli, Zengilan, Jabrayil, Fuzuli, Khojavand, Shusha, Khojali, Khankendi, Aghdam and Tartar"]},{"k":"p","s":["You should follow Azerbaijani national government and local authorities’ advice in areas that have not been cleared of mines or unexploded ordnance."]},{"k":"p","s":["Find out more about ",["why FCDO advises against travel","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["UK government support"]},{"k":"p","s":["Help for British nationals is extremely limited in the areas where we advise against travel."]},{"k":"h","s":["Regional escalation"]},{"k":"p","s":["There is a heightened risk of regional tension. Escalation could lead to travel disruption, including airspace closures and other unanticipated impacts."]},{"k":"p","s":["British nationals should take sensible precautions, considering their own individual circumstances. These include:"]},{"k":"li","s":["read ",["if you’re affected by a crisis abroad - GOV.UK","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],". This includes guidance on “how to prepare for a crisis” with suggestions on what you might include in your emergency supplies and “what to do in a crisis”"]},{"k":"li","s":["sign up to FCDO Travel Advice email alerts"]},{"k":"li","s":["monitor local and international media for the latest information"]},{"k":"li","s":["follow the instructions of the local authorities"]},{"k":"p","s":["For information on crossing the border from Iran into Azerbaijan, see ",["Entry requirements","https://www.gov.uk/foreign-travel-advice/azerbaijan/entry-requirements"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["FCDO provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/azerbaijan/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Azerbaijan’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Azerbaijan set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Azerbaijani Embassy in the UK.","https://london.mfa.gov.az/en"]]},{"k":"h","s":["Entering Azerbaijan across the land border from Iran"]},{"k":"p","s":["The border between Azerbaijan and Iran is closed. But British nationals might be able to cross at the Astara border crossing with special authorisation from the Government of Azerbaijan, which must be facilitated by the British Embassy in Baku. British nationals seeking entry into Azerbaijan should ",["contact the FCDO","https://www.contact.service.csd.fcdo.gov.uk/home"]," before travelling to the border crossing at Astara, indicating whether you are contacting from Iran or from the UK on behalf of a relative. Other border crossings to Azerbaijan remain closed."]},{"k":"p","s":["British nationals will need to provide personal details (name, date of birth, passport information). The British Embassy will provide confirmation and a code from the Azerbaijani authorities. This can take several weeks. You should not travel to the border until you have received confirmation. You will need to show the code before crossing. You will also need to apply for a visa through the normal process. See ‘applying for a visa’."]},{"k":"p","s":["If you intend to leave Iran overland, you do so at your own risk. In Iran, holding a British passport or having perceived connections to the UK can be reason enough for the Iranian authorities to detain you."]},{"k":"p","s":["Read more FCDO advice ",["if you’re affected by a crisis abroad","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Azerbaijan as a visitor, your passport must usually have an ‘expiry date’ at least 6 months after the date you arrive and at least 2 blank pages for entry stamps. See ‘visa requirements’ for more details."]},{"k":"p","s":["To enter Azerbaijan as a resident, your passport must have an ‘expiry date’ at least 3 months after the expiry date of your temporary or permanent residence permit."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"p","s":["If you need to travel on a UK Emergency Travel Document, check the visa requirements below before making your travel arrangements."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"hs","s":["British-Azerbaijani dual nationals"]},{"k":"p","s":["Azerbaijan does not recognise dual nationality, but does not prohibit Azerbaijani nationals from holding dual nationality. You must inform the local Azerbaijani Embassy or State Migration Service within one month of taking up another nationality. If you do not, this can impact the level of consular support FCDO will be able to provide."]},{"k":"p","s":["If you’re a British passport holder with links to Azerbaijan, through birth or otherwise, and need to check your nationality status, contact the ",["State Migration Service","https://migration.gov.az/en"]," before you travel."]},{"k":"hs","s":["Checks at border control"]},{"k":"p","s":["Anyone who has previously visited certain areas in south-western Azerbaijan, including the town of Khankendi, without the permission of the Azerbaijani authorities could be denied entry to Azerbaijan. You should contact the nearest embassy or consulate of Azerbaijan before you travel. See ",["Regional Risks","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["Entry via land or sea borders"]},{"k":"p","s":["You can only enter Azerbaijan via air travel without restrictions. Entry via a land or sea border is restricted. Once in Azerbaijan you can exit via air or sea routes. If you want to leave Azerbaijan by road, you need permission from the authorities."]},{"k":"h","s":["Entering with a vehicle"]},{"k":"p","s":["To enter Azerbaijan with a vehicle, you need to arrange for the vehicle to be shipped to Baku, where you have to arrange for collection at Customs. You need to provide Power of Attorney and pay fees as required."]},{"k":"h","s":["Borders with Iran and Georgia"]},{"k":"p","s":["The land borders between Iran and Azerbaijan, and Georgia and Azerbaijan are temporarily closed."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You must have a visa to visit Azerbaijan."]},{"k":"hs","s":["Applying for a visa"]},{"k":"p","s":["You can apply and pay for a visa from the ",["ASAN Visa (e-visa) service","https://evisa.gov.az/en/"],". Apply at least 3 days in advance. An urgent 3-hour service is available for an additional fee."]},{"k":"p","s":["E-visas are normally single entry and allow a 30-day visit within a 90-day period of validity. You must print out the e-visa and bring it with your passport to show on arrival. Officials will check that your passport is valid for 3 months after the visa expiry date. This means your passport must be valid for at least 6 months after the date you arrive in Azerbaijan."]},{"k":"p","s":["For other types of visas, such as a business visa or a work permit, contact the ",["Azerbaijani Embassy in the UK","https://london.mfa.gov.az/en"]," at least one month before your travel date."]},{"k":"hs","s":["FIFA U-15 World Cup and Festival 2026"]},{"k":"p","s":["If you are travelling to Azerbaijan for the FIFA U-15 World Cup and Festival 2026, ",["simplified visa arrangements","https://london.mfa.gov.az/en/category/facilated-visa-procedures-for-the-fifa-u-15-world-cup-festival-2026"]," are in place from 22 September to 5 November 2026. Eligible travellers can obtain a visa on arrival at Azerbaijan’s international airports. You must have either an official invitation letter from the Association of Football Federations of Azerbaijan (AFFA) or confirmation of accreditation through FIFA’s electronic registration system."]},{"k":"hs","s":["Travelling on a UK Emergency Travel Document"]},{"k":"p","s":["Azerbaijan accepts UK Emergency Travel Documents (ETDs) for entry and must be accompanied by a visa to enter Azerbaijan. You cannot use a UK ETD to apply for an Azerbaijani e-visa, as the e-visa system does not recognise ETDs as eligible travel documents. If you are travelling on a UK ETD, you must apply for a visa directly through an Azerbaijani embassy before you travel. Contact the Azerbaijani Embassy in the country where you are applying for advice on the application process and processing times."]},{"k":"hs","s":["Extending your visa"]},{"k":"p","s":["You can extend your 30 days by applying to the ",["State Migration Service","https://migration.gov.az/en/page/72"]," at least 3 days before the end of the permitted stay."]},{"k":"p","s":["If you overstay your visa without permission, you may have to leave the country within 48 hours. Contact the ",["State Migration Service","https://migration.gov.az/en/contact/59"]," as soon as possible. They can issue a letter giving you permission to leave. You will have to pay a fine of 300 to 400 Azerbaijani manat. Make sure you get a receipt as proof of payment."]},{"k":"p","s":["If you are in Azerbaijan, you can also call the Migration Information Centre on 919."]},{"k":"hs","s":["Registering with the authorities"]},{"k":"p","s":["If you’re staying in Azerbaijan for longer than 15 days, you must ",["register with the State Migration Service","https://eservice.migration.gov.az/?lang=en"]," online or in person. If you do not register you will have to pay a fine to the ",["State Migration Service","https://migration.gov.az/en/contact/59"]," before you are able to leave the country. Hotels often provide this service for their guests, but you must do it yourself if you are staying in an apartment or private residence."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Azerbaijan guide","https://travelhealthpro.org.uk/country/17/azerbaijan#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Azerbaijan. You must declare anything that may be prohibited or subject to tax or duty. Follow advice from your airline about items you should declare."]},{"k":"p","s":["If you plan to use a local SIM card for more than 30 days, you must register it and pay a fee at a local post office. If you do not declare your device or register your sim card, it may not work on local networks and your device could be locked. You will need to give the IMEI number of your mobile, which you can find in settings, or by dialling *#06#."]},{"k":"hs","s":["Exporting carpets and antiques"]},{"k":"p","s":["You need an export certificate to take antiques or art like carpets, samovars, copperware or paintings out of Azerbaijan. Your vendor will give you a certificate, or they are available from the ",["Azerbaijan National Carpet Museum","https://azcarpetmuseum.az/en/contact"],"."]},{"k":"h","s":["Safety and security"]},{"k":"p","s":["This guide also has safety advice for ",["regions of Azerbaijan","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Azerbaijan"]},{"k":"p","s":["Terrorists are likely to try to carry out attacks in Azerbaijan."]},{"k":"p","s":["Terrorism attacks could be indiscriminate, including in places visited by foreign nationals, such as:"]},{"k":"li","s":["hotels, restaurants and pubs"]},{"k":"li","s":["energy sector facilities"]},{"k":"li","s":["religious sites and places of worship"]},{"k":"li","s":["shopping centres and crowded places"]},{"k":"li","s":["embassies and government buildings"]},{"k":"li","s":["sporting and cultural events"]},{"k":"li","s":["transport hubs"]},{"k":"p","s":["Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Political situation"]},{"k":"p","s":["The political situation in Azerbaijan is generally calm, but demonstrations and opposition rallies can occur."]},{"k":"p","s":["Avoid large gatherings and any demonstrations. They are illegal and there could be a swift response from the authorities. Monitor the media for information about possible demonstrations and be alert to local and regional developments, which may trigger public disturbances."]},{"k":"p","s":["If you are a British journalist, make sure you are clearly identifiable."]},{"k":"hs","s":["Armenia-Azerbaijan tensions"]},{"k":"p","s":["Tensions between Armenia and Azerbaijan have calmed and the risk of further conflict has decreased, including in the areas of those regions affected by conflict in 2020 and 2023. The FCDO continues to advise against all but essential travel to some areas in south-western Azerbaijan due to the risks from mines or unexploded ordnance from former conflict, and advises against all travel within 5km of the border with Armenia. See ",["Regional Risks","https://www.gov.uk/foreign-travel-advice/azerbaijan/regional-risks"],"."]},{"k":"h","s":["Crime"]},{"k":"p","s":["Crime levels in Baku are generally low. Be alert to possible bag-snatching or mugging, particularly if you are carrying large amounts of cash or valuables. The risk is higher after dark in the centre of town. Avoid displaying large sums of money or expensive-looking valuables and do not walk alone at night."]},{"k":"hs","s":["Dealing with officials"]},{"k":"p","s":["There are occasionally reports of government officials asking foreign nationals to make undocumented payments. If you think you have been mistreated by a traffic policeman or health professional, report your case to the relevant government department."]},{"k":"hs","s":["Bank card fraud"]},{"k":"p","s":["Fraudsters can steal your card details without you noticing. Take extra care to guard against card skimming when using credit cards or withdrawing cash from ATMs. Use ATMs inside banks where possible, check street ATMs for signs of tampering, and always keep your card in sight when paying in shops and restaurants."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"p","s":["Azerbaijan is a largely secular society, although most of the population is Muslim. Religion is usually considered a private matter."]},{"k":"p","s":["Some areas, such as Martyrs’ Alley, are especially sensitive. Disruptive or disrespectful conduct in or around such area may result in police action, including fines or being summoned to the police station."]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Police sometimes carry out checks of identity documents. Carry your passport at all times. Keep a copy of the photo page in a safe place."]},{"k":"hs","s":["Dress code"]},{"k":"p","s":["In Baku local and foreign women usually dress in conservative western-style clothing. It is now more acceptable for men to wear shorts in Baku in the summer months. Outside of Baku it may still be frowned on, and you may receive unwelcome attention."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country."]},{"k":"p","s":["Most restaurants, cafés, shops and other services in Azerbaijan continue to operate during Ramadan. Some businesses may adjust their opening hours or offer special Ramadan arrangements."]},{"k":"p","s":["During Ramadan, you should:"]},{"k":"li","s":["check opening hours of shops and restaurants, as these may vary"]},{"k":"li","s":["respect local religious customs and traditions"]},{"k":"li","s":["follow local dress codes, particularly when visiting religious sites - clothing that does not meet local dress codes may cause more offence at this time"]},{"k":"li","s":["be aware that some people may be fasting and may be more tired than usual, especially in the late afternoon and early evening"]},{"k":"li","s":["be patient and considerate towards those who are observing Ramadan"]},{"k":"hs","s":["Smoking restrictions"]},{"k":"p","s":["Smoking is restricted to designated areas. You can be fined for dropping smoking-related litter. Use bins provided."]},{"k":"hs","s":["Illegal drugs"]},{"k":"p","s":["Possession or use of illegal drugs, including cannabis, carries severe penalties. You should expect a long jail sentence and heavy fines for possessing, using, or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Azerbaijan have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Using cameras and drones in sensitive locations"]},{"k":"p","s":["Be aware of cultural sensitivities when photographing mosques, churches and other religious sites or sites of commemoration, such as the Alley of Martyrs in Baku. If in doubt, ask for permission."]},{"k":"p","s":["Military bases, equipment and installations in any condition are considered sensitive areas, and visitors have been detained and questioned while attempting to visit or photograph them."]},{"k":"p","s":["If you do not have temporary or permanent residence rights in Azerbaijan, you are not allowed to import drones. Any drones will be confiscated by the State Customs Office at the port or border and returned upon departure."]},{"k":"p","s":["Unmanned drones cannot be rented to individuals without a valid taxpayer identification number (TIN). If you have a TIN, special permission from the ",["Ministry of Digital Development and Transport","https://mincom.gov.az/en"]," is required. Manned drones can be rented without requiring permission."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["While same-sex sexual activity is not illegal, LGBT+ people in Azerbaijan tend to keep a low profile. Showing affection in public is frowned upon, especially outside of Baku and among the older generation."]},{"k":"p","s":["Holding hands or embracing between men is usually a sign of friendship."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Azerbaijan, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and read the ",["RAC guide on driving in Azerbaijan","https://www.rac.co.uk/drive/travel/country/azerbaijan/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["It is illegal to use right-hand-drive cars in Azerbaijan."]},{"k":"hs","s":["Inter-country road travel"]},{"k":"p","s":["There may be delays in transporting vehicles to Azerbaijan. It is best not to pay for non-refundable onward travel. Azerbaijan Caspian Shipping Closed Joint-Stock Company has ",["details of onward shipment from Baku to Turkmenistan and Kazakhstan","https://www.asco.az/en/pages/2/96"],"."]},{"k":"hs","s":["Licences and permits"]},{"k":"p","s":["You’ll need to have both the ",["1968 version of the international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," and your UK driving licence with you in the car. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["After one month, you will need an Azerbaijani driving licence issued through the ",["ASAN Service Offices","https://asan.gov.az/en"],". You need to carry a ",["green card","https://www.gov.uk/vehicle-insurance/driving-abroad"]," as proof you’re insured to drive in Azerbaijan."]},{"k":"p","s":["If you’re planning to hire a car, check with your car hire company for information on their requirements before you travel."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Many vehicles are poorly maintained, and the standard of driving is erratic. Accidents are common, mainly due to poor or reckless driving and inconsistent enforcement of traffic rules. Drivers often ignore one-way signs."]},{"k":"p","s":["Road closures and diversions are often unmarked. Take care when driving at night as many roads are of poor quality and badly lit. Traffic lights that are flashing amber at night mean cars can proceed with caution in either direction."]},{"k":"p","s":["Drink-driving is a serious offence in in Azerbaijan. If you are tested and found to have any alcohol in your system, you may get a severe fine and possibly a prison sentence."]},{"k":"p","s":["In the winter months snowfall often causes problems. Pack your vehicle with a blanket, shovel, torch, snacks and old carpet to help if you get stuck in snow."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Try to arrange to be picked up and dropped off as close to your hotel or apartment entrance as possible by a private or company driver, or use a known firm or taxi app."]},{"k":"p","s":["Some visitors have reported being severely overcharged by local taxis. When using taxis, agree a fare up front, or make sure the taxi meter is switched on. Check that the taxi has working seatbelts."]},{"k":"p","s":["Ride-hailing apps such as Uber and Bolt are widely available in Azerbaijan."]},{"k":"hs","s":["Rail travel"]},{"k":"p","s":["If you travel by train, secure your valuables, do not leave the compartment unattended, and lock the door from the inside, if your compartment allows."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There is a risk of earthquakes across the Caucasus region, although there have been no recent serious earthquakes in Azerbaijan. The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Regional risks"]},{"k":"p","s":["This section has safety advice for regions of Azerbaijan. It only covers regions where the Foreign, Commonwealth & Development Office (FCDO) has specific advice."]},{"k":"p","s":["You should also read ",["FCDO’s overall travel advice","https://www.gov.uk/foreign-travel-advice/azerbaijan"]," and ",["safety and security advice","https://www.gov.uk/foreign-travel-advice/azerbaijan/safety-and-security"],"."]},{"k":"hs","s":["South-western Azerbaijan (those regions affected by conflict in 2020 and 2023)"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) advises against all but essential travel to some areas in south-western Azerbaijan, including districts in and around the region formerly known as “Nagorno-Karabakh” due to the risks from leftover military equipment and weapons from former conflict. This includes:"]},{"k":"li","s":["the districts (‘rayons’) of Kelbajar, Lachin, Qubadli, Zengilan, Jabrayil, Fuzuli, Khojavand, Shusha, Khojali, Khankendi, Aghdam and Tartar"]},{"k":"p","s":["It is illegal to enter certain areas in south-western Azerbaijan, without the permission of the Azerbaijani authorities. Anyone who has previously visited these areas, including the town of Khankendi, without the permission of Azerbaijani authorities could be denied entry to Azerbaijan. You should contact the nearest embassy or consulate of Azerbaijan before you travel."]},{"k":"p","s":["Whilst tensions have calmed and the risk of further conflict has decreased, there remains a risk of unexploded weapons and landmines in south-western Azerbaijan. The Azerbaijani authorities are working to remove unexploded weapons and landmines."]},{"k":"p","s":["Follow Azerbaijani national government and local authorities’ advice in areas that have not been cleared of mines or unexploded ordnance. If you come across an unexploded weapon or landmine do not approach it or touch it. Make a note of where you saw it and notify the authorities on 102 or 112. Beware of more unexploded weapons or landmines nearby."]},{"k":"h","s":["Azerbaijan-Armenia border"]},{"k":"p","s":["The border with Armenia remains closed. The FCDO also advises against all travel to within 5km of the rest of the border with Armenia. Note that this does not include the border of Azerbaijan’s Nakhchivan exclave with Armenia."]},{"k":"h","s":["Azerbaijan-Russia border"]},{"k":"p","s":["The land border between Azerbaijan and Russia (Dagestan) is closed. The FCDO continues to advise against all travel to Russia. For further details, see ",["FCDO’s travel advice for Russia","https://www.gov.uk/foreign-travel-advice/russia"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Call 103 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Azerbaijan","https://travelhealthpro.org.uk/country/17/azerbaijan#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["Go to TravelHealthPro to see ",["what health risks you’ll face in Azerbaijan","https://travelhealthpro.org.uk/country/17/azerbaijan"],"."]},{"k":"p","s":["Altitude sickness is a risk in some parts of Azerbaijan, including the ski resorts of Shahdag and Tufangdag in the Gusar district, Lake Batabat in Nakhchivan, and the Talysh mountains. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare facilities in Azerbaijan"]},{"k":"p","s":["Medical facilities outside Baku are very limited. Carry a comprehensive first aid kit for any trips out of Baku. Even in Baku, serious illness or injury may require evacuation to Turkey or Western Europe. Make sure you have appropriate travel health insurance."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Azerbaijan","https://www.gov.uk/government/publications/azerbaijan-list-of-medical-facilitiespractitioners"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Azerbaijan"]},{"k":"p","s":["Ambulance: 103"]},{"k":"p","s":["Fire: 101"]},{"k":"p","s":["Police: 102"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=azerbaijan"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=azerbaijan"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=azerbaijan"]," in Azerbaijan"]},{"k":"li","s":["dealing with a ",["death in Azerbaijan","https://www.gov.uk/government/publications/azerbaijan-bereavement-information"]]},{"k":"li","s":["being ",["arrested or imprisoned in Azerbaijan","https://www.gov.uk/government/publications/azerbaijan-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/azerbaijan/british-embassy-baku"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/azerbaijan/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Azerbaijan","https://www.gov.uk/government/publications/overseas-business-risk-azerbaijan"]," on how to manage political, economic, and business security-related risks."]}],"chars":25491,"change":"New information about entry requirements for the upcoming FIFA U-15 World Cup and Festival 2026 and travelling on a UK Emergency Travel Document to Azerbaijan. Updated information about visa requirements and entering Azerbaijan across the land border from Iran ('Entry requirements' page)."},"https://www.gov.uk/foreign-travel-advice/bulgaria":{"r":"govuk","at":"2026-11-17T16:16Z","sha":"1a10ecf3da2abcb27de19ce9c4b6daab916b5a296cca9234124db96c3589a81e","read":"https://www.gov.uk/api/content/foreign-travel-advice/bulgaria","bytes":78474,"x":"fulltext v1","title":"Bulgaria travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2013-02-20T00:00:00+00:00","mod":"2026-08-11T10:18:49+01:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/bulgaria/email-signup"]," when this advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/travelaware/"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of the current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Bulgaria set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the Bulgarian Embassy in the UK."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Bulgaria follows ",["Schengen area rules","https://europa.eu/youreurope/citizens/travel/entry-exit/non-eu-nationals/index_en.htm"],". Your passport must have:"]},{"k":"li","s":["have a ‘date of issue’ less than 10 years before the date you arrive – if you renewed your passport before 1 October 2018, it might have a date of issue that is more than 10 years ago, making it invalid for entry to the Schengen area"]},{"k":"li","s":["an ‘expiry date’ at least 3 months after the date you plan to leave the Schengen area (the expiry date does not need to be within 10 years of the date of issue)"]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"p","s":["Carry your passport if you travel from Bulgaria to other Schengen area countries. Border guards may check it if you cross land or river borders into Greece or Romania, both in the Schengen area."]},{"k":"p","s":["There are no routine checks when travelling by air or sea within the Schengen area, but carry your passport in case you’re asked for it. Most carriers require official photo ID."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual Citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["You can ",["travel without a visa to the Schengen area","https://www.gov.uk/travel-to-eu-schengen-area"],", which includes Bulgaria, for up to 90 days in any 180-day period. This applies if you travel:"]},{"k":"li","s":["as a tourist"]},{"k":"li","s":["to visit family or friends"]},{"k":"li","s":["to attend business meetings, cultural or sports events"]},{"k":"li","s":["for short-term studies or training"]},{"k":"p","s":["The ",["requirements for working in Bulgaria","https://www.gov.uk/guidance/travel-to-bulgaria-for-work"]," are different."]},{"k":"p","s":["If you’re travelling to other Schengen countries as well, make sure your whole visit is within the 90-day visa-free limit. Visits to Schengen countries in the 180 days before you travel count towards your 90 days. If you overstay the 90-day visa-free limit, you may be banned from entering Schengen countries for up to 3 years."]},{"k":"p","s":["At Bulgarian border control, you may also need to:"]},{"k":"li","s":["show proof of your accommodation, for example, a hotel booking confirmation or proof of address for a second home"]},{"k":"li","s":["show proof of your travel insurance"]},{"k":"li","s":["show a return or onward ticket"]},{"k":"li","s":["prove that you have enough money for your stay – the amount varies depending on your accommodation"]},{"k":"hs","s":["Staying longer than 90 days in a 180-day period"]},{"k":"p","s":["To stay longer, check which type of visa or work permit you need with the Bulgarian Embassy in the UK."]},{"k":"p","s":["If you’re in Bulgaria with a residence permit or long-stay visa, this does not count towards your 90-day visa-free limit."]},{"k":"p","s":["Read about ",["entry processes if you live in Bulgaria","https://www.gov.uk/guidance/living-in-bulgaria#passports-and-travel"],"."]},{"k":"h","s":["New Schengen entry requirements"]},{"k":"p","s":["The European Union’s (EU) new Entry/Exit System (EES) is now being implemented across the Schengen area."]},{"k":"p","s":["This means that when you travel into the Schengen area for short stays, you may need to register your biometric details, such as fingerprints and a photo. There is no cost for EES registration."]},{"k":"p","s":["On your first visit into a Schengen country, you may be asked to register your details at a special booth before proceeding to the immigration desk. Follow directions from your travel operator or the staff at your port of entry. You may also need to provide either your fingerprint or photo when you leave the Schengen area. Children aged 11 or younger will not have their fingerprints scanned but can be required to have their photo taken."]},{"k":"p","s":["You do not need to take any action before you arrive at the border on entry to the Schengen area, but EES may take each passenger extra time to complete so be prepared to wait longer than usual at the border and to allow more time for immigration controls when you depart the Schengen area. If you are departing the Schengen area by plane, allow extra time to reach your departure gate as EES checks may take place before boarding."]},{"k":"p","s":["EES is replacing the previous system of manually stamping passports when visitors arrive in the Schengen area for short stays. You may be asked to input biometric details every time you enter or exit."]},{"k":"p","s":["If you enter the Schengen area through the Port of Dover, Eurotunnel at Folkestone or Eurostar at St Pancras International, any information will be taken at the border before you leave the UK."]},{"k":"p","s":["Your digital EES record is valid for 3 years."]},{"k":"p","s":["Read more ",["information on the EU Entry/Exit System and to understand which countries are in the Schengen area","https://www.gov.uk/guidance/eu-entryexit-system"],"."]},{"k":"p","s":["If you are long-term resident in a Schengen country, you are exempt from EES in all Schengen countries. The full list of EES exemptions is on ",["the EU’s official Travel Europe website.","https://travel-europe.europa.eu/en/ees/to-whom-does-ees-not-apply"]]},{"k":"p","s":["If you believe you have been incorrectly entered into EES or your record of time spent in the Schengen area is incorrect, approach border officials when you next cross the Schengen border and request a correction. If you are exempt, carry documentation confirming your status. If you believe your time spent in the Schengen area has been recorded incorrectly, raise this with border officials and be prepared to provide supporting evidence if requested."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["For details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Bulgaria guide","https://travelhealthpro.org.uk/country/36/bulgaria#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods you can take into or out of Bulgaria","https://customs.bg/wps/portal/agency-en/home/info-citizens/Important%20notice%20for%20travelers"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"hs","s":["Taking food and drink into Bulgaria"]},{"k":"p","s":["You cannot take ",["meat, milk or products containing them into EU countries","https://ec.europa.eu/food/animals/animalproducts/personal_imports_en"],". There are some exceptions such as powdered baby milk, baby food and special foods or pet feed required for medical reasons."]},{"k":"hs","s":["Taking money into Bulgaria"]},{"k":"p","s":["As of 1 January 2026, the currency of Bulgaria will be the euro. Bulgarian lev will still be accepted until 31 January, but can be exchanged for euros free of charge at Bulgarian banks until 30 June 2026."]},{"k":"p","s":["There may be some temporary disruption to card payments and to cash withdrawals from ATMs around 31 December 2025 to 1 January 2026 due to the changeover in currency. Cash payments will be unaffected."]},{"k":"p","s":["Major credit and debit cards are accepted in most banks and hotels. Most ATMs accept standard international credit and debit cards."]},{"k":"p","s":["Pounds sterling and US dollars are easily exchanged for euros. Only exchange money at reliable places such as banks and currency exchange bureaux."]},{"k":"p","s":["Declare ",["cash or travellers cheques if the value is 10,000 euros or more","https://customs.bg/wps/portal/agency-en/home/info-citizens/Carrying%20of%20cash,%20precious%20metals,%20gems%20and%20items%20containing%20them%20or%20made%20of%20them"],". You will get a certified declaration to show you brought it in with you. If you do not, your money could be seized when you leave."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Bulgaria"]},{"k":"p","s":["Although there’s no recent history of terrorism in Bulgaria, attacks cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate, including in places visited by foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Protests and demonstrations"]},{"k":"p","s":["There are occasional political protests in towns and cities across Bulgaria. They can cause disruption to transport as protestors or police may set up roadblocks. Most protests are peaceful but there have been occasional incidents of violence, including by the police. Avoid all protests and follow the advice of local authorities."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting yourself and your belongings"]},{"k":"p","s":["Take sensible precautions to protect yourself from street crime, particularly in larger cities and late at night. Beware of any attempts to distract you. Watch out for pickpockets and bag thefts in tourist areas, on buses and trains and major public transport hubs, including airports."]},{"k":"p","s":["Thefts from unattended cars at petrol stations have increased. Lock your car when going inside the petrol station to pay for your fuel."]},{"k":"p","s":["Tourists are targeted by thieves and pickpockets in Sunny Beach and other larger cities and resorts. Thefts on the bus from Nessebar to Sunny Beach have also increased. Do not take valuables to the beach and be wary of poorly lit roads around the resort at night."]},{"k":"hs","s":["Scams"]},{"k":"p","s":["Some tourists have been the victims of overcharging in so-called ‘gentlemen’s clubs’ in Sofia and in some resorts including Bansko, Borovets and Sunny Beach. Overcharging can amount to hundreds of pounds. Victims can be threatened with violence if they refuse to pay."]},{"k":"p","s":["Get recommendations for bars and clubs from your hotel or other holidaymakers. When paying by card make sure the transaction is completed in your presence and be wary if asked to re-enter your PIN."]},{"k":"hs","s":["Thefts from accommodation"]},{"k":"p","s":["There have been burglaries from hotel rooms in Sunny Beach. Make sure you lock your room (including windows and balcony doors) and keep valuables locked in a safe."]},{"k":"p","s":["There have been break-ins at properties in the residential areas of cities, and rural areas."]},{"k":"hs","s":["Thefts from cars"]},{"k":"p","s":["Criminals may puncture your tyres or flag down your car. When you get out, the thieves can distract you and steal from your vehicle. Make sure the boot is locked and your luggage is secure."]},{"k":"hs","s":["Property fraud"]},{"k":"p","s":["Buyers have been defrauded while buying property. Be cautious and get legal advice before you buy. Only deal with established and reputable real estate agents or with other contacts who you know to be reliable and genuine."]},{"k":"p","s":["See ",["more details about buying property","https://www.gov.uk/guidance/living-in-bulgaria#accommodation-and-buying-property"],"."]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Personal ID"]},{"k":"p","s":["Always carry ID. A printed copy of the photo page of your passport is acceptable."]},{"k":"hs","s":["Illegal drugs and sex offences"]},{"k":"p","s":["The Bulgarian authorities treat all drug-related and sex offences very seriously. Any foreign nationals convicted of such offences can expect a prison sentence. Illegal drugs, including cannabis, carry severe penalties. You should expect a long jail sentence and heavy fines for possessing, using, or smuggling illegal drugs, including when transiting through the airport."]},{"k":"p","s":["Airports in Bulgaria have excellent technology and security for detecting illegal items. This is also used to scan the baggage of transiting passengers."]},{"k":"hs","s":["Drunken and disorderly behaviour"]},{"k":"p","s":["Offences relating to drunken, disorderly behaviour and hooliganism may be treated more seriously than in the UK. Police can arrest or fine anyone for loud and boisterous behaviour or urination in public places."]},{"k":"hs","s":["Football matches"]},{"k":"p","s":["Crowd control measures and stewarding can be different from the UK and there have been a small number of incidents where ‘throwdown fireworks’ such as firecrackers or bangers have been set off in stadiums, risking injuries. Stay aware of your surroundings and be alert in crowded venues."]},{"k":"hs","s":["Using cameras and binoculars in secure areas"]},{"k":"p","s":["Avoid taking photographs near potentially sensitive areas like military establishments. If in doubt, ask permission."]},{"k":"hs","s":["Working with migrants in border regions"]},{"k":"p","s":["Assisting people who have entered Bulgaria illegally, or who are passing through Bulgaria to claim asylum in another country, risks breaking Bulgarian laws. It makes no difference whether you are helping them for profit or not – you are still at risk of breaking Bulgarian law. You can be arrested, detained and charged if you are suspected of facilitating illegal entry or stay in Bulgaria, including by helping with accommodation or transport. If you travel to Bulgaria to support civil society organisations working with migrants, seek advice from local expert organisations such as the ",["IOM","https://bulgaria.iom.int/"],", ",["UNHCR","https://www.unhcr.org/countries/bulgaria"]," or ",["Bulgarian Helsinki Committee","https://www.bghelsinki.org/en"]," to make sure that your proposed actions do not break Bulgarian laws."]},{"k":"hs","s":["Race-related incidents"]},{"k":"p","s":["The majority of visitors experience no difficulties related to their race, ethnicity or religious beliefs. However there have been a small number of verbal and physical attacks against ethnic minority UK nationals, including residents, in Bulgaria, and others have experienced unwanted attention or harassment in public places."]},{"k":"p","s":["Instances have increased at times of demonstrations organised by groups connected to populist or right-wing movements. Avoid all protests and stay aware of your surroundings, particularly when travelling alone or at night."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Same-sex sexual activity is not illegal, but public attitudes are less tolerant than in the UK and the LGBT+ community generally keeps a low profile."]},{"k":"p","s":["There are a few gay bars and clubs in Sofia. The city also holds the annual Sofia Pride. Sofia Pride is growing in popularity and was attended in recent years by over 10,000 people. However, it attracts some negative attention locally and is held with a heightened police presence and security measures. If you want to join the parade, read the organisers’ Sofia Pride safety rules."]},{"k":"p","s":["In recent years, some verbal abuse and threatening behaviour was directed at people attending events related to Sofia Pride, including foreign visitors. You can report any hate crime to the organisers and the local police."]},{"k":"p","s":["Attitudes outside Sofia tend to be more conservative. There have been isolated cases of hostility towards people perceived to be from LGBT+ communities reported in Burgas and Plovdiv. You can find local information on LGBT+ issues in Bulgaria on the website of the ",["Bulgarian Helsinki Committee","https://www.bghelsinki.org/en/themes/lgbti"],"."]},{"k":"p","s":["Read more ",["advice for LGBT+ travellers","https://www.gov.uk/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Face-covering ban"]},{"k":"p","s":["Covering your face with a niqab, burka or similar head covering in public places is illegal in Bulgaria and police could give you a fine. This applies in public buildings, streets, parks, restaurants, shops and on public transport."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"p","s":["Sports activities like skiing, potholing and mountaineering, and sports classed as particularly dangerous – mountain biking, climbing, paragliding or BASE jumping – all carry risks. Your insurance should include:"]},{"k":"li","s":["mountain rescue services"]},{"k":"li","s":["helicopter costs"]},{"k":"li","s":["repatriation to your home country or possible transfer to neighbouring countries for treatment"]},{"k":"p","s":["There’s more ",["information about mountain insurance","https://en.redcross.bg/activities/activities2"]," on the Bulgarian Red Cross website."]},{"k":"hs","s":["Quad biking and motorbikes"]},{"k":"p","s":["Quad biking is an extreme sport and carries the risk of serious injury or death. You need specific travel insurance to cover quad biking. Always read the details of your insurance cover, especially the small print and exclusions on your policy."]},{"k":"p","s":["Make sure you are given full instructions and training before your activity."]},{"k":"p","s":["Insurance sold by the hire company usually only provides third-party insurance. It’s likely you will be charged for any damage to the rental vehicle and you may face arrest if you do not pay."]},{"k":"p","s":["If you hire a motorbike, you need a full motorbike licence. Make sure the vehicle is in good condition. Drivers and passengers must wear helmets. Failure to do so may invalidate your insurance."]},{"k":"hs","s":["Swimming and water sports"]},{"k":"p","s":["Obey any warning signs at coastal areas and beaches. Follow instructions from lifeguards and observe the flag indicators if they are present. Follow local advice if jellyfish or sea urchins are present."]},{"k":"p","s":["For more advice, see ",["Water safety on holiday","https://www.rlss.org.uk/safety-on-holiday"]," from the Royal Life Saving Society."]},{"k":"p","s":["Book activities at a licensed water sports centre and before you start:"]},{"k":"li","s":["make sure the paperwork is completed"]},{"k":"li","s":["ask for a safety demonstration"]},{"k":"li","s":["make sure you know how to call for help"]},{"k":"p","s":["See ⁠ ",["watersports safety advice","https://www.rospa.com/leisure-water-safety/water/advice/watersports-abroad"]," from the Royal Society for the Prevention of Accidents (ROSPA)."]},{"k":"hs","s":["Winter sports"]},{"k":"p","s":["Read advice about ",["preparing for winter sports abroad","https://www.gov.uk/guidance/winter-sports-stay-safe-on-the-slopes"],". The Bulgarian Mountain Rescue service publishes ",["safety rules on the ski slopes","https://www.pss-bg.bg/pravila-za-bezopasnost-po-ski-pistite/"]," (in Bulgarian)."]},{"k":"p","s":["Avalanches are a risk in some areas. Always check the local snow and weather conditions if you plan to ski off-piste, and ski with a guide. There’s more information about avalanche risk from the ",["Bulgarian Mountain Rescue Service","https://www.pss-bg.bg/"]," (in Bulgarian)."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you plan to drive in Bulgaria, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"]," and check the ",["rules of the road in the RAC’s Bulgaria guide","https://www.rac.co.uk/drive/travel/country/bulgaria/"],". The guide lists driving regulations and other legal requirements you need to be aware of."]},{"k":"p","s":["If you bring your own car to Bulgaria, you must have:"]},{"k":"li","s":["your driving licence"]},{"k":"li","s":["all original registration and ownership documents"]},{"k":"li","s":["proof of insurance that is valid in Bulgaria – although you are not required to have a green card to drive in Bulgaria, you may need it in some neighbouring countries"]},{"k":"p","s":["Check if you need a ",["UK sticker to drive your car outside the UK","https://www.gov.uk/displaying-number-plates/flags-identifiers-and-stickers"],"."]},{"k":"p","s":["If it’s a hired car, you must keep the contract document. Border officials will impound your vehicle if they are not satisfied that you own it or have permission to use it in Bulgaria."]},{"k":"p","s":["Vehicles that are registered outside the EU are considered to be ‘temporarily imported’ when driven inside Bulgaria. If your car is stolen in Bulgaria, you will be liable for import duty and related taxes."]},{"k":"p","s":["See ",["driving requirements if you live in Bulgaria","https://www.gov.uk/guidance/living-in-bulgaria#driving-in-bulgaria"],"."]},{"k":"hs","s":["Driving conditions"]},{"k":"p","s":["Road conditions can be dangerous. Take care when driving, particularly at night and outside major cities. Many roads (and pavements) are in poor repair and roadworks are often unmarked and unlit at night. Driving standards are generally poor, and drivers can be aggressive, particularly on motorways. Avoid confrontations."]},{"k":"p","s":["There may be slow-moving cars and animal-drawn vehicles on the roads, particularly in rural areas."]},{"k":"p","s":["You must drive with side lights or dipped headlights, even during the daytime. Keep to the speed limit and make sure your vehicle is roadworthy. Traffic police issue on-the-spot fines for minor violations."]},{"k":"p","s":["Bulgaria has strict penalties for driving under the influence of alcohol and drugs, and doing so could lead to vehicle confiscation, a prison sentence and fines. If you receive a penalty and do not own the vehicle, you could be required to pay a fine equivalent to the vehicle’s value."]},{"k":"hs","s":["Tolls"]},{"k":"p","s":["If you want to use motorways and main roads outside towns, you’ll need to buy a digital vignette in advance of your journey. The vignette is a form of toll. If you use the roads without a vignette, traffic police will issue a fine. You can ",["buy a vignette online","https://www.tolltickets.com/en/country/bulgarien/"],"."]},{"k":"hs","s":["Taxis"]},{"k":"p","s":["Taxis may not be in very good condition. Avoid taxis parked outside hotels or in tourist areas. Ask your hotel to call a taxi or flag down a passing taxi with a green ‘available’ light in the window. Check the licence sticker and the tariffs on the window before getting in as costs can vary considerably. Licensed taxis run by ‘Yellow’ operators are the most reliable."]},{"k":"p","s":["There are regular reports of robberies and threatening behaviour by taxi drivers in Sunny Beach. Use a taxi recommended by your tour operator or accommodation provider."]},{"k":"p","s":["There has been an increase in unlicensed taxis from Sofia airport overcharging passengers. If you’re travelling from the airport, make sure you take an official, licensed taxi. There is an ",["official taxi booking office","https://sofia-airport.eu/en/access/transportation/#by-taxi"]," in the arrivals hall. Check that the taxi meter is working before starting your journey."]},{"k":"hs","s":["Rail and bus travel"]},{"k":"p","s":["Thieves operate on trains. Make sure that documents and valuables are safe. The train system is very poor by European standards. There have been several fires on Bulgarian trains. Bulgaria has a comprehensive rail network, but trains can be cancelled at short notice. For travel updates see the ",["Bulgaria Railways website","https://www.bdz.bg/en"],"."]},{"k":"p","s":["The roadworthiness of vehicles and driving standards are not always good, and there have been a number of serious accidents in recent years."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Wildfires"]},{"k":"p","s":["In summer and early autumn, Bulgaria is on a regular alert for wildfires. There is danger of large-scale and quick-spreading fires in forests and fields. Follow media reports and the advice of local authorities if wildfires occur in your area."]},{"k":"hs","s":["Flooding"]},{"k":"p","s":["Many parts of Bulgaria flood following heavy rains. Flooding is usually localised but can occasionally be widespread and has caused deaths. Watch for weather warnings on the National Institute of Meteorology and Hydrology website."]},{"k":"hs","s":["Earthquakes"]},{"k":"p","s":["There are earthquakes and small tremors throughout the year, usually without serious consequences. The last significant earthquakes were in 1928."]},{"k":"p","s":["The US Federal Emergency Management Agency website has advice about ",["what to do before, during and after an earthquake","https://www.ready.gov/earthquakes"],"."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 112 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance or medical assistance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Bulgaria","https://travelhealthpro.org.uk/country/36/bulgaria#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Bulgaria","https://travelhealthpro.org.uk/country/36/bulgaria"],", including biting insects and ticks."]},{"k":"p","s":["Altitude sickness is a risk in parts of Bulgaria. Read more about ",["altitude sickness on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/26/altitude-illness"],"."]},{"k":"hs","s":["Stray dogs"]},{"k":"p","s":["Stray dogs are common and can be dangerous. Avoid getting too close to dogs, especially if they are in a pack. Take any animal bites seriously and seek immediate medical advice as rabies and other animal-borne diseases are present in Bulgaria."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Bulgaria"]},{"k":"p","s":["FCDO has a list of ",["medical providers in Bulgaria","https://www.gov.uk/government/publications/bulgaria-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"p","s":["Most Bulgarian hospitals are basic and old-fashioned compared to those in the UK. Standards of medical care are generally good, but specialised equipment and treatment may not be available. Hospital staff rarely speak English."]},{"k":"p","s":["Private clinics and hospitals are generally well-equipped and not expensive in comparison with the UK."]},{"k":"p","s":["Foreign tourists have sometimes been overcharged in private clinics in tourist resorts. Hotels or resorts may call private ambulances. If you use private medical services, agree a price in advance. Ask whether there is a suitable public health facility nearby if you want to use a health insurance card, as these are not accepted by many private hospitals."]},{"k":"hs","s":["Health insurance cards"]},{"k":"p","s":["To get medically necessary state healthcare in Bulgaria, you need a Global Health Insurance Card (GHIC) or a European Health Insurance Card (EHIC)."]},{"k":"p","s":["The NHS’s ",["getting healthcare abroad webpage","https://www.nhs.uk/using-the-nhs/healthcare-abroad/apply-for-a-free-uk-global-health-insurance-card-ghic/"]," has details about:"]},{"k":"li","s":["how to apply for a GHIC"]},{"k":"li","s":["how to get temporary cover if you lose your card or it does not arrive in time"]},{"k":"li","s":["who qualifies for a new EHIC instead of a GHIC"]},{"k":"li","s":["what treatment counts as medically necessary"]},{"k":"p","s":["A GHIC or EHIC is not an alternative to travel insurance. You may have costs your GHIC or EHIC does not cover, including:"]},{"k":"li","s":["changes to travel and accommodation bookings"]},{"k":"li","s":["additional standard costs for treatment"]},{"k":"li","s":["medical repatriation to the UK"]},{"k":"li","s":["treatment that is ruled non-urgent"]},{"k":"li","s":["private healthcare"]},{"k":"li","s":["private clinics"]},{"k":"p","s":["Read about ",["healthcare if you live in Bulgaria","https://www.gov.uk/guidance/healthcare-in-bulgaria"],"."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Bulgaria"]},{"k":"p","s":["Telephone: 112 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Bulgaria&serviceType=lawyers"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Bulgaria&serviceType=funeralDirectors"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find?country=Bulgaria&serviceType=translatorsInterpreters"]," in Bulgaria"]},{"k":"li","s":["dealing with a ",["death in Bulgaria","https://www.gov.uk/guidance/what-to-do-after-a-british-person-dies-in-bulgaria"]]},{"k":"li","s":["being ",["arrested in Bulgaria","https://www.gov.uk/government/publications/bulgaria-prisoner-pack/information-pack-for-british-nationals-detained-or-imprisoned-in-bulgaria"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/bulgaria/british-embassy-sofia"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/bulgaria/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Bulgaria","https://www.gov.uk/government/publications/overseas-business-risk-bulgaria"]," on how to manage political, economic, and business security-related risks."]}],"chars":26362,"change":"Updated information on European Entry-Exit System (EES) (‘Entry requirements’ page)."},"https://www.gov.uk/foreign-travel-advice/brunei":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"c83b995c0aa72fa4e40415d9635d83be18c38aba15f748c0e7828edd0044d4ae","read":"https://www.gov.uk/api/content/foreign-travel-advice/brunei","bytes":52861,"x":"fulltext v1","title":"Brunei travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2012-12-14T00:00:00+00:00","mod":"2026-03-19T14:05:48+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"h","s":["Global travel impacts due to escalation in the Middle East"]},{"k":"p","s":["Escalation in the Middle East has caused widespread travel disruption, including airspace closures, delayed and cancelled flights."]},{"k":"p","s":["Your travel plans may be affected, even if your destination is not in the Middle East. Before you travel:"]},{"k":"li","s":["check travel advice for any countries or territories you are transiting through"]},{"k":"li","s":["check for the latest updates from your airline or tour operator"]},{"k":"li","s":["review your travel insurance policy for coverage"]},{"k":"li","s":["monitor local and international media for the latest information and sign up for travel advice email alerts"]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/brunei/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Brunei’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Brunei set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the ",["Brunei High Commission in the UK","https://www.mfa.gov.bn/uk-london/SitePages/Home.aspx"],"."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["To enter Brunei, your passport must have an ‘expiry date’ at least 6 months after the date you arrive. It must not be damaged or have any pages missing. If your passport does not meet these conditions, you may be refused entry and detained."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"p","s":["If you’re a dual national, you should use the same passport to enter and exit Brunei. The passport you use for entry will determine your nationality in Brunei."]},{"k":"hs","s":["British-Brunei dual nationals"]},{"k":"p","s":["Brunei does not recognise the dual nationality of Bruneians. The immigration authorities can refuse your entry if you hold a Bruneian passport and a passport of a different nationality."]},{"k":"p","s":["If you enter on a Brunei passport, you cannot access British consular assistance, as you will be treated as a Bruneian national."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["British citizen passport holders may enter Brunei as visitors for up to 90 days without a visa. If you have another type of British nationality, check visa requirements with Brunei immigration authorities."]},{"k":"p","s":["To stay longer or if you’re travelling for work, study, business travel or other reasons, you must meet the Brunei government’s entry requirements. Check which type of visa or work permit you need with the ",["Brunei High Commission in the UK","https://www.mfa.gov.bn/uk-london/SitePages/Home.aspx"],"."]},{"k":"p","s":["Make sure you get your passport stamped."]},{"k":"p","s":["Make sure you get your passport stamped when you enter Brunei."]},{"k":"hs","s":["Overstaying your visa"]},{"k":"p","s":["Do not overstay your visa or violate the terms of entry. Penalties include detention and caning."]},{"k":"h","s":["Declaration form"]},{"k":"p","s":["You must ",["submit an e-arrival declaration form","https://www.imm.gov.bn/"]," to enter Brunei. Do this before you travel as it may be requested at check-in. You do not need to complete the arrival form if you are not passing through immigration."]},{"k":"p","s":["You must also complete the ",["Health Declaration Form","https://www.healthinfo.gov.bn/travel#/user/login"]," before or upon arrival. More information can be found at the ",["Ministry of Health website","https://www.moh.gov.bn/"],"."]},{"k":"h","s":["Land and sea travel"]},{"k":"p","s":["Check ",["border post opening hours","https://www.immigration.gov.bn/SitePages/Pos-Pos%20Kawalan.aspx"]," before you travel. They are not open 24 hours. Make sure your exit and entry stamps are correct before leaving the border post."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Brunei, you must have certificates to prove you’ve had:"]},{"k":"li","s":["a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"]]},{"k":"li","s":["a polio vaccine, in some circumstances"]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Brunei guide","https://travelhealthpro.org.uk/country/35/brunei#Vaccine_Recommendations"],"."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about ",["goods and the amount of alcohol you can take into and out of Brunei","https://bdnsw.mofe.gov.bn/Pages/ImpExpProh-RestictionGoods.aspx"],". You must declare anything that may be prohibited or subject to tax or duty."]},{"k":"p","s":["You can complete a declaration through the Customs.BN app or on arrival at the airport. Download the app for ",["Android","https://play.google.com/store/apps/details?id=rced.egnc.customsbn&pli=1https://play.google.com/store/apps/details?id=rced.egnc.customsbn&pli=1"]," or ",["iOS","https://apps.apple.com/us/app/customs-bn/id6449696019"],"."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Brunei"]},{"k":"p","s":["Although there’s no recent history of terrorism in Brunei, attacks cannot be ruled out."]},{"k":"p","s":["Attacks could be indiscriminate including in places visited by foreign nationals. Stay aware of your surroundings, keep up to date with local media reports and follow the advice of local authorities."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Crime levels are low, but there are occasional incidents of petty crime against tourists as well as house burglaries. You should:"]},{"k":"li","s":["take care of your passport"]},{"k":"li","s":["avoid carrying valuables with you"]},{"k":"li","s":["not leave possessions in unattended vehicles, even if out of sight"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"p","s":["Islam is the official religion in Brunei. Respect local traditions, customs, laws and religions. Make sure that your actions do not cause offence, especially during the holy month of Ramadan. There may be serious penalties for doing something that might not be illegal in the UK but is in Brunei."]},{"k":"p","s":["Places of business and offices, including shops and restaurants, shut between midday and 2pm every Friday for prayers."]},{"k":"p","s":["Friday is a non-working day for government offices and local schools. Government offices and state schools open on Saturdays instead."]},{"k":"hs","s":["Ramadan"]},{"k":"p","s":["Ramadan is a holy month for Muslims. The dates vary by year and country. During this time, it is against the law to be seen eating or drinking in public during fasting hours. You must also not smoke in public."]},{"k":"p","s":["You should dress modestly. For example, do not wear shorts in government and public buildings such as health centres."]},{"k":"p","s":["Get more advice when you arrive from your tour guide, hotel or business contacts."]},{"k":"hs","s":["Criticism of the Bruneian Royal Family"]},{"k":"p","s":["His Majesty The Sultan and other members of the Bruneian Royal Family are highly revered and public criticism of them causes great offence and may result in legal action."]},{"k":"hs","s":["Relationships outside marriage"]},{"k":"p","s":["Adultery and closeness in private between an unmarried man and woman is illegal if one person is a Muslim. In general, public displays of affection may cause offence."]},{"k":"hs","s":["Pornographic material"]},{"k":"p","s":["Possession of pornographic material is illegal."]},{"k":"hs","s":["Firearms, ammunition and explosives"]},{"k":"p","s":["Brunei has very strict laws against the possession of firearms, blank or live ammunition and explosives, including fireworks and firecrackers. Do not carry these items or replicas into Brunei."]},{"k":"hs","s":["LGBT+ travellers"]},{"k":"p","s":["Brunei criminalises same-sex sexual activity. Sentences include a maximum penalty of death by stoning, whipping, imprisonment and fines. However there is currently a moratorium on the death penalty and there is limited evidence of same-sex activity laws being implemented in recent years. The gender expression of trans people is also criminalised and this law is occasionally enforced with fines."]},{"k":"p","s":["Read ",["advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"],"."]},{"k":"hs","s":["Illegal drugs penalties"]},{"k":"p","s":["There are severe penalties for drug offences in Brunei including, in some cases, the death penalty. Other crimes may be punished by caning and lengthy prison sentences."]},{"k":"hs","s":["Alcohol laws and bans"]},{"k":"p","s":["The sale of alcohol and tobacco in Brunei is illegal. Non-Muslims aged 17 and over may import a limited amount of alcohol. This must be declared to the customs authorities on arrival and drunk in private."]},{"k":"hs","s":["Smoking and e-cigarette bans"]},{"k":"p","s":["Smoking is illegal in certain public places, including shopping and eating areas, bus stops and stations, car parks and in close proximity to any public buildings."]},{"k":"h","s":["Outdoor activities and adventure tourism"]},{"k":"hs","s":["Hiking and mountaineering"]},{"k":"p","s":["Police advise against hiking alone in the forest, including at well-known recreation areas. It’s easy to get lost when visiting the rainforest. You should:"]},{"k":"li","s":["use recognised and well-known guides"]},{"k":"li","s":["stay on paths and trails, rather than pushing through the undergrowth"]},{"k":"li","s":["always carry food and water with you"]},{"k":"li","s":["consider carrying a whistle to attract attention and a torch"]},{"k":"li","s":["wear closed-toe shoes"]},{"k":"h","s":["Wildlife"]},{"k":"hs","s":["Saltwater crocodiles"]},{"k":"p","s":["Saltwater crocodiles have attacked and killed people fishing on riverbanks around Bandar. Crocodiles have also been seen on beaches and in the ponds of the Panaga golf course. You should:"]},{"k":"li","s":["pay attention to signs warning of crocodiles"]},{"k":"li","s":["stay away from the water’s edge"]},{"k":"li","s":["seek local advice on taking further precautions"]},{"k":"hs","s":["Venomous snakes"]},{"k":"p","s":["There are a number of venomous snakes in Brunei. If you see a snake while outdoors:"]},{"k":"li","s":["keep your distance"]},{"k":"li","s":["wait for the snake to move away"]},{"k":"p","s":["If you find a snake indoors or outside in a confined space, like a garden, call the fire service (‘bomba’) on 995."]},{"k":"p","s":["The RIPAS public hospital in Bandar Seri Begawan carries antivenom. Get medical advice if a snake bites you."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Brunei, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can drive in Brunei with a valid UK driving licence for up to 90 days. You’ll then need to ",["apply for a Bruneian licence from the Land Transport Department","https://www.jpd.gov.bn/SitePages/Land%20Transport%20Department/Services/Driving%20Licenses.aspx"],"."]},{"k":"p","s":["If your vehicle is not registered in Brunei, you can only buy motor fuel at ",["14 designated filling stations","https://bsm.com.bn/products/shell-fuels/shell-v-power/"],", to a maximum of 250 litres. Petrol stations will only sell premium “V-Power” fuel to foreign cars. You can usually only pay in cash."]},{"k":"p","s":["If you’re driving to Malaysia with a Bruneian registered car, the same is true – foreign registered vehicles are only permitted to buy premium RON97 fuel (not the subsidised RON95 fuel) and this is not available in all petrol stations. Make sure to fill up before leaving a city."]},{"k":"p","s":["Driving standards are different from the UK. Vehicles do not always stop at red lights or pedestrian crossings. It is common for drivers not to use seatbelts or child car seats and to speed. Road surfaces are uneven and accidents are common. Animals such as monitor lizards, snakes and monkeys could be on the roads."]},{"k":"p","s":["If you’re involved in a road accident as a driver, do not leave the scene or move the vehicle until the police arrive (call 993 for the police)."]},{"k":"hs","s":["Sea travel"]},{"k":"p","s":["Small boats carry passengers across to the water village in Bandar and along the rivers on cruises. You should:"]},{"k":"li","s":["check there are adequate life jackets for all passengers, including children"]},{"k":"li","s":["keep hands inside the boat, as there may be river crocodiles"]},{"k":"p","s":["If you’re taking a longer trip, for example, a wildlife cruise, get local recommendations and plan your trip in advance."]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have an existing health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 991 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Brunei","https://travelhealthpro.org.uk/country/35/brunei#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Brunei","https://travelhealthpro.org.uk/country/35/brunei"],"."]},{"k":"h","s":["Medication"]},{"k":"p","s":["The legal status and regulation of some medicines prescribed or bought in the UK can be different in other countries."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"p","s":["Most branded pharmaceuticals are readily available, though some items available without a prescription in the UK may need a doctor’s prescription in Brunei."]},{"k":"h","s":["Healthcare in Brunei"]},{"k":"p","s":["Standards of healthcare in Brunei are generally acceptable, though basic hospital supplies can occasionally run low. There are 2 significant medical facilities, the Government General Hospital (RIPAS) in Bandar Seri Begawan and the private Jerudong Park Medical Centre (JPMC)."]},{"k":"p","s":["You may need medical evacuation to Singapore if there are complications. Make sure you have adequate travel health insurance and accessible funds to cover the cost of any medical treatment abroad and repatriation."]},{"k":"p","s":["FCDO has a ",["list of medical providers in Brunei","https://www.gov.uk/government/publications/brunei-list-of-medical-facilities-and-practitioners"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read the ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Brunei"]},{"k":"p","s":["Ambulance: 991"]},{"k":"p","s":["Fire: 995"]},{"k":"p","s":["Police: 993"]},{"k":"p","s":["Search and rescue: 998"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers in Brunei","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=brunei"]]},{"k":"li","s":["dealing with a ",["death in Brunei","https://www.gov.uk/government/publications/bereavement-information-pack-brunei"]]},{"k":"li","s":["being ",["arrested or imprisoned in Brunei","https://www.gov.uk/government/publications/brunei-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/brunei/british-high-commission-bandar-seri-begawan"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/brunei/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Brunei","https://www.gov.uk/government/publications/overseas-business-risk-brunei"]," on how to manage political, economic, and business security-related risks."]}],"chars":15161,"change":"Updated information about global travel impacts due to escalation in the Middle East (‘Warnings and insurance’ page)."},"https://theconversation.com/5-ontario-education-unions-hold-strike-votes-as-cuts-squeeze-classrooms-294338":{"r":"conversation","at":"2026-11-17T16:30Z","sha":"e714743df150e97e2b778eaae6ba04671129e87f95064aca360f836697e93cfd","read":"https://theconversation.com/5-ontario-education-unions-hold-strike-votes-as-cuts-squeeze-classrooms-294338","bytes":188382,"x":"fulltext v1","title":"5 Ontario education unions hold strike votes as cuts squeeze classrooms","by":[{"n":"Chantal Mancini","r":"Adjunct Assistant Professor of Labour Studies, McMaster University"}],"pub":"2026-10-29T14:52:00Z","mod":"","blocks":[{"k":"p","s":["Five major unions representing Ontario education workers will hold ",["strike votes in November","https://nowtoronto.com/news/ontario-education-unions-strike-votes-november-2026/"],". Their contracts expired Aug. 31, 2026."]},{"k":"p","s":["The move signals a potential showdown with Premier Doug Ford’s Conservative government after many months of warnings about deteriorating learning and working conditions in the province’s schools. As both a labour studies scholar and a secondary teacher, I am uniquely positioned to provide the context."]},{"k":"p","s":["Strike votes do not necessarily mean that workers will walk off the job. In fact, ",["95 per cent of labour disputes in Canada are resolved without a strike","https://www.pearson.com/en-ca/subject-catalog/p/labour-relations/P200000010237?view=educator"],"."]},{"k":"p","s":["Unions use strike votes as a pressure tactic to signal to employers ",["that workers are united in their cause","https://www.cbc.ca/news/canada/toronto/queens-park-teachers-rally-public-education-9.7394914"],". The co-ordination of the unions’ votes is a clear message to the government that they’re prepared to collectively pursue their goals."]},{"k":"p","s":["Why are unions now sending this message? The current stall in negotiations follows the ",["provincial government’s indication to unions that it wants greater control over negotiating issues","https://www.etfo.ca/news-publications/media-releases/joint-statement-calandras-bargaining-bluster-falls-flat"],", such as staffing timelines related to transfer, surplus and redundancy, as well as professional development funding ",["and contracting out.","https://www.cambridgetoday.ca/local-news/unions-criticize-outsourcing-of-custodial-staff-at-new-cambridge-joint-use-school-12752246"]]},{"k":"p","s":["This comes ",["as unions say","https://www.instagram.com/p/DcThI0slh1_/"]," classrooms are under severe strain driven by the government’s chronic ",["underfunding of education","https://www.thestar.com/politics/ontario-s-education-funding-per-student-is-decreasing-after-inflation-watchdog-finds/article_aa8b1bab-cf4a-439a-9b9a-a8d2881e5589.html"],"."]},{"k":"h","s":["Greater control over staffing?"]},{"k":"p","s":["A move towards greater government control over staffing would fall in line with the Ministry of Education’s centralization of power, following a ",["provincial takeover of eight school boards","https://globalnews.ca/news/11717907/york-catholic-district-school-takeover/"]," and ",["restrictions on the power of elected trustees","https://www.thetrillium.ca/news/education-and-training/breaking-ford-government-to-restrict-number-and-duties-of-school-board-trustees-12134818"],"."]},{"k":"p","s":["Unions know that ",["exerting greater control over costs via centralization can be translated into additional cuts","https://doi.org/10.18740/S4TC7R"]," (and more underfunding and erosion of working and learning conditions)."]},{"k":"p","s":["Centralization also cuts out democratic input by local workers and their unions (and parents and trustees)."]},{"k":"p","s":["Read more: ",["Attacks on school boards threaten local democracy","https://theconversation.com/attacks-on-school-boards-threaten-local-democracy-261895"]]},{"k":"h","s":["Staffing cuts, lack of resources"]},{"k":"p","s":["Education workers are ",["facing significant staffing cuts","https://www.ctvnews.ca/video/2026/10/09/education-other-public-service-workers-saw-the-brunt-of-job-cuts-in-september/"],". Teachers are increasingly faced with larger ",["classes of students","https://www.etfo.ca/news-publications/media-releases/etfo-bringing-class-size-fight-to-bargaining-table"]," with ",["diverse learning and behavioural needs","https://www.ctf-fce.ca/class-size-isnt-the-whole-story/"]," they say they are unable to meet."]},{"k":"p","s":["The Canadian Teachers’ Federation notes that across provinces, teachers say students who need help aren’t getting it and teaching time is being lost as a result: Teachers in ",["Québec,","https://theconversation.com/quebecs-teacher-strike-offers-lessons-on-the-urgent-need-to-support-public-education-220363"]," ",["Saskatchewan","https://theconversation.com/saskatchewan-teacher-strike-its-about-bargaining-for-the-common-good-221095"]," and ",["Alberta","https://www.cbc.ca/news/canada/calgary/classroom-complexity-teacher-voices-9.7099882"]," made the same point in recent bargaining."]},{"k":"p","s":["Reports point to ",["rising school violence and burnout","https://www.thestar.com/news/ontario/violence-harassment-and-burnout-ontarios-education-workers-are-in-crisis-study-finds/article_ac79b129-d6e0-4d93-a2fc-9bac94912c58.html"]," driven by a lack of resources and supports. ",["Ministry of Education data","https://www.cbc.ca/news/canada/toronto/ontario-teacher-shortage-ministry-of-educaiton-1.7339837"]," warns of a teacher recruitment and retention problem expected to worsen by 2027."]},{"k":"p","s":["Read more: ",["To improve literacy, Ontario should invest in students and educators","https://theconversation.com/to-improve-literacy-ontario-should-invest-in-students-and-educators-280758"]]},{"k":"p","s":[["Educational assistants","https://www.cbc.ca/news/canada/toronto/ea-shortage-ontario-9.7268522"]," are in short supply, making the situation particularly difficult for ",["students with special learning needs","https://www.cbc.ca/news/canada/toronto/ontario-auditor-general-report-education-9.7196608"],"."]},{"k":"p","s":["Education unions say ",["education workers have had enough.","https://underfunded.ca/"]," The Ford government says it’s made ",["record investments in education,","https://paulcalandra.com/ontario-making-record-investments-to-put-student-achievement-first/"]," but ",["research estimates","https://www.policyalternatives.ca/news-research/ontario-school-funding-shortfall-continues-to-grow-reaching-6-4-billion-since-2018/"]," a $6.5-billion-dollar shortfall in the system since the Conservatives came to power in 2018."]},{"k":"p","s":["With ",["school boards posting record deficits","https://globalnews.ca/news/11955405/ontario-supervisor-deficits/"],", students are ",["losing programs","https://www.thetrillium.ca/news/education-and-training/an-unmitigated-disaster-for-students-outcry-grows-over-education-cuts-outside-tdsb-headquarters-ahead-of-delayed-parent-advisory-meeting-12399438"]," and ",["schools are in a state of disrepair","https://www.cbc.ca/news/canada/toronto/ontario-fao-school-repair-construction-shortfall-1.7412722"],"."]},{"k":"p","s":["Ontario teachers and other education workers (like educational assistants, early childhood educators, speech language pathologists, school psychologists, school custodians, office administrators) are represented by multiple unions. These unions will need to demonstrate unprecedented solidarity if they hope to achieve the funding improvements and retain local control over bargaining staffing and contracting out."]},{"k":"h","s":["Local bargaining matters"]},{"k":"p","s":["Education unions in the province must follow a specific negotiations process set out in the ",["School Boards Collective Bargaining Act","https://www.ontario.ca/laws/statute/14s05"],"."]},{"k":"p","s":["The act was passed by ",["the Liberals in 2014","https://news.ontario.ca/en/release/29016/ontario-strengthening-education-sector-for-students"],", and can be understood as part of an ",["overall trend towards province-wide negotiations","https://www.saskoer.ca/understandingcanadianschools/chapter/9-7-collective-bargaining/"]," across Canada."]},{"k":"p","s":["This legislation transformed education bargaining. It required that each union, at their own bargaining table with the government, must agree to which things will be bargained “centrally” with the government, and which items will be bargained “locally” with the school boards before any actual negotiations take place."]},{"k":"p","s":["Normally, ",["central issues bargained with the government","https://www.cbc.ca/news/canada/toronto/ontario-teachers-unions-labour-negotiations-9.7327115"]," consist of high-cost items such wages, benefits and sick leave."]},{"k":"p","s":["Preserving local bargaining over staffing matters for educators because teachers and support staff have different needs. Each school board, and corresponding local union, will have issues that are unique to their community."]},{"k":"p","s":["Take, for example, staff transfers: In a school board area serving Hamilton, Ont., transferring a teacher from one school to another might seem more workable because the distance between the two most outlying schools is ",["arguably not that long of a drive","https://www.hwdsb.on.ca/school-boundary-maps"],". In a northern school board, or even in the Toronto District School Board serving the greater Toronto area, a transfer could mean relocating your family due to the distance or the commute."]},{"k":"p","s":["Unions have sent the disputes over what must be negotiated with the province and what must be negotiated with school boards ",["to the Ontario Labour Relations Board","https://www.thoroldtoday.ca/local-news/elementary-teachers-contract-talks-on-hold-over-dispute-that-could-stretch-into-school-year-12622662#google_vignette"],"."]},{"k":"p","s":["Hearings ",["are concluding","https://www.innisfiltoday.ca/local-news/ontario-education-unions-ramp-up-strike-preparations-as-bargaining-remains-stalled-12809519"],", with a decision expected weeks later. The timing will likely coincide with the unions’ strike vote results."]},{"k":"h","s":["How would a job action proceed?"]},{"k":"p","s":["Unions would need to demonstrate a majority of members voting yes for any job action to proceed."]},{"k":"p","s":["The parties must first engage in a period of meaningful bargaining and other mandatory ",["labour relations processes","https://osstftoronto.ca/wp-content/uploads/2026/06/EN-Barganing-Process-chart.pdf"]," before any work-to-rule, strike or lockout can occur."]},{"k":"p","s":["Unions must provide five days’ written notice before engaging in job action. School boards must provide the same notice before locking out workers."]},{"k":"h","s":["Gearing up for conflict?"]},{"k":"p","s":["Like ",["earlier governments","https://www.cbc.ca/news/canada/toronto/liberals-strike-historic-wage-freeze-deal-with-catholic-teachers-1.1185659"],", the Ford government has proven it will resort to ",["divide-and-conquer strategies","https://globalnews.ca/news/9923475/ontario-teachers-union-strike-education-minister/"],"."]},{"k":"p","s":["In 2022, only weeks after education contracts expired, the premier ",["removed CUPE education workers’ right to strike","https://breachmedia.ca/the-inside-story-of-how-education-workers-beat-back-doug-ford/"]," by invoking the notwithstanding clause."]},{"k":"p","s":["It was not until ",["other unions threatened a general strike","https://www.theglobeandmail.com/business/article-ford-cupe-notwithstanding-canadian-unions/"]," that he backed down."]},{"k":"p","s":["Read more: ",["Ontario school strike: Government’s use of the notwithstanding clause — again — is an assault on labour relations","https://theconversation.com/ontario-school-strike-governments-use-of-the-notwithstanding-clause-again-is-an-assault-on-labour-relations-193824"]]},{"k":"p","s":["It’s clear this time that the government is gearing up for conflict once again. Just before contracts expired, a ",["media report","https://www.thetrillium.ca/news/education-and-training/ford-government-preparing-education-ads-taking-aim-at-teacher-unions-as-contract-talks-grind-to-a-halt-leaked-script-12674031"]," leaked the government’s plan for an ad campaign taking aim at education workers’ use of sick leave."]},{"k":"p","s":["The complex nature of collective bargaining in the education sector makes this round’s outcome tough to predict."]},{"k":"p","s":["Education unions — particularly those who represent teachers — tend to favour work-to-rule campaigns and rotating strikes over total walkouts. They are mindful of both ",["public opinion","https://www.ctvnews.ca/ottawa/article/ontarians-express-support-for-cupe-as-education-workers-strike-continues-poll-finds/"]," and the threat of ",["back-to-work legislation","https://www.tvo.org/article/ontario-forces-teachers-back-to-work-here-responses-from-across-the-province"],"."]},{"k":"p","s":["However, CUPE has indicated that this time around, ",["it will escalate quickly to a strike if necessary.","https://www.thestar.com/politics/provincial/forget-work-to-rule-school-support-staff-will-go-straight-to-strike-if-necessary-union-says/article_933da333-b747-42c7-a504-69280ed8f242.html"]," Whether the rest of the ",["255,000 education workers in the province","https://www.etfo.ca/news-publications/media-releases/ontario-education-unions-serve-notice-to-bargain-2026"]," would join them remains to be seen."]},{"k":"p","s":["What this fight will look like will be determined in the weeks ahead. Clearly, there is much at stake."]},{"k":"p","s":["This is an updated version of a story originally published on Oct. 29, 2026. It clarifies that the author is both a labour studies scholar and a secondary teacher."]}],"chars":7193},"https://www.gov.uk/foreign-travel-advice/macao":{"r":"govuk","at":"2026-11-17T16:30Z","sha":"03a5f35b2ffd23f3e3b69966f17eefdb4998e2b627ba4d97e1d758a771741172","read":"https://www.gov.uk/api/content/foreign-travel-advice/macao","bytes":45637,"x":"fulltext v1","title":"Macao (SAR of China) travel advice","by":[{"n":"Foreign, Commonwealth & Development Office","r":""}],"pub":"2012-12-14T00:00:00+00:00","mod":"2025-12-11T11:32:17+00:00","blocks":[{"k":"h","s":["Warnings and insurance"]},{"k":"p","s":["This travel advice covers the Macao Special Administrative Region (SAR). For mainland China, see ",["travel advice for China","https://www.gov.uk/foreign-travel-advice/china"],"."]},{"k":"h","s":["Dual Chinese-British nationality"]},{"k":"p","s":["Macao does not recognise dual nationality. If you have both British and Chinese nationality, the local authorities may treat you as a Chinese citizen, even if you enter Macao on a full “British citizen” passport. If this is the case, the British Consulate-General may not be able to offer you consular help."]},{"k":"p","s":["If you have formally renounced Chinese citizenship, carry evidence that you have done so."]},{"k":"p","s":["See guidance on ",["nationality in China","https://www.gov.uk/government/publications/nationality-in-china"],"."]},{"k":"h","s":["Before you travel"]},{"k":"p","s":["No travel can be guaranteed safe. Read all the advice in this guide. You may also find it helpful to:"]},{"k":"li","s":["see ",["general advice for women travellers","https://www.gov.uk/guidance/advice-for-women-travelling-abroad"]]},{"k":"li","s":["read our ",["guide on disability and travel abroad","https://www.gov.uk/government/publications/disabled-travellers"]]},{"k":"li","s":["see ",["general advice for LGBT+ travellers","https://www.gov.uk/guidance/lesbian-gay-bisexual-and-transgender-foreign-travel-advice"]]},{"k":"li","s":["read about ",["safety for solo and independent travel","https://www.gov.uk/guidance/solo-and-independent-travel"]]},{"k":"li","s":["see ",["advice on volunteering and adventure travel abroad","https://www.gov.uk/guidance/safer-adventure-travel-and-volunteering-overseas"]]},{"k":"hs","s":["Travel insurance"]},{"k":"p","s":["If you choose to travel, research your destinations and ",["get appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"],". Insurance should cover your itinerary, planned activities and expenses in an emergency."]},{"k":"h","s":["About FCDO travel advice"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) provides advice about risks of travel to help you make informed decisions. Find out ",["more about FCDO travel advice","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice"],"."]},{"k":"hs","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/macao/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"li","s":[["Travel Aware on Instagram","https://www.instagram.com/accounts/login/?next=https%3A%2F%2Fwww.instagram.com%2Ftravelaware%2F&is_from_rle"]]},{"k":"h","s":["Entry requirements"]},{"k":"p","s":["This information is for people travelling on a full ",["‘British citizen’ passport","https://www.gov.uk/types-of-british-nationality"]," from the UK. It is based on the UK government’s understanding of Macao’s current rules for the most common types of travel."]},{"k":"p","s":["The authorities in Macao set and enforce entry rules. If you’re not sure how these requirements apply to you, contact the Chinese Embassy in the UK."]},{"k":"h","s":["Passport validity requirements"]},{"k":"p","s":["Your passport must have an ‘expiry date’ at least 90 days after the date you leave Macao."]},{"k":"p","s":["Check with your travel provider that your passport and other travel documents meet requirements. ",["Renew your passport","https://www.gov.uk/renew-adult-passport/renew"]," if you need to."]},{"k":"p","s":["You will be denied entry if you do not have a valid travel document or try to use a passport that has been reported lost or stolen."]},{"k":"h","s":["Dual nationals"]},{"k":"p","s":["When returning to the UK, British citizens must carry a valid ",["British passport","https://www.gov.uk/browse/abroad/passports"]," or ",["certificate of entitlement","https://www.gov.uk/right-of-abode/apply-for-a-certificate-of-entitlement"],". See ",["Dual citizenship","https://www.gov.uk/dual-citizenship"],"."]},{"k":"p","s":["Other types of ",["British nationals who are exempt from ETA","https://www.gov.uk/eta/when-not-need-eta"]," must also carry a valid British passport when entering the UK."]},{"k":"h","s":["Visa requirements"]},{"k":"p","s":["Macao is part of the People’s Republic of China, but it remains a Special Administrative Region (SAR) with its own immigration controls."]},{"k":"p","s":["You can visit Macao for up to 6 months without a visa, for tourism and to undertake unpaid business activities."]},{"k":"p","s":["To stay longer, to do paid work, to study, or for other reasons, you must get a visa before arrival. Check which type of visa you need with the ",["Macao Immigration Department","https://www.macaotourism.gov.mo/en/travelessential/before-you-travel/entry-requirements"],"."]},{"k":"hs","s":["Travelling through Macao to China"]},{"k":"p","s":["If you plan to travel through Macao to mainland China on a British passport, you must get a Chinese visa before you arrive at the border. If not, you could be fined or detained by the mainland Chinese authorities."]},{"k":"p","s":["If you enter and leave Macao through mainland China, you must get a double or multiple entry visa to re-enter mainland China."]},{"k":"p","s":["The mainland Chinese authorities may carry out thorough checks at border crossings, including of your electronic devices."]},{"k":"h","s":["Vaccine requirements"]},{"k":"p","s":["To enter Macao, you must have a certificate to prove you’ve had a yellow fever vaccination if you’re coming from a ",["country listed as a transmission risk","https://nathnacyfzone.org.uk/factsheet/65/countries-with-risk-of-yellow-fever-transmission"],"."]},{"k":"p","s":["For full details about medical entry requirements and recommended vaccinations, see ",["TravelHealthPro’s Macao guide","https://travelhealthpro.org.uk/country/50/chinamacao#Vaccine_Recommendations"],"."]},{"k":"h","s":["Accommodation"]},{"k":"p","s":["You must stay in licensed accommodation. You could be fined up to 3,000 Macanese pataca (about £300) if you stay in illegal accommodation. Find accommodation or check your accommodation is licensed on the ",["Macao Tourism Office","https://www.macaotourism.gov.mo/en/accommodation/"]," website."]},{"k":"h","s":["Customs rules"]},{"k":"p","s":["There are strict rules about goods you can take into or out of Macao. You must ",["declare anything that may be prohibited or subject to tax or duty","https://www.macaotourism.gov.mo/en/travelessential/before-you-travel/entry-requirements?tab=customs"],"."]},{"k":"p","s":["Macao airport has a ",["passenger guide","https://www.macau-airport.com/en/passenger-guide/arrival"]," that explains the allowances."]},{"k":"h","s":["Safety and security"]},{"k":"h","s":["Terrorism"]},{"k":"p","s":["There is a high threat of terrorist attack globally affecting UK interests and British nationals, including from groups and individuals who view the UK and British nationals as targets. Stay aware of your surroundings at all times."]},{"k":"p","s":["UK Counter Terrorism Policing has information and advice on ",["staying safe","https://www.counterterrorism.police.uk/runhidetell/"]," and what to do in the event of a terrorist attack. Find out ",["how to reduce your risk from terrorism while abroad","https://www.gov.uk/guidance/reduce-your-risk-from-terrorism-while-abroad"],"."]},{"k":"hs","s":["Terrorism in Macao"]},{"k":"p","s":["Although there’s no recent history of terrorism in Macao, attacks cannot be ruled out."]},{"k":"h","s":["Crime"]},{"k":"hs","s":["Protecting your belongings"]},{"k":"p","s":["Crime levels are low but pickpocketing and other street crime does happen. You should take particular care of:"]},{"k":"li","s":["passports, credit cards and money in crowded areas"]},{"k":"li","s":["your belongings when checking out of hotels"]},{"k":"li","s":["your wallet and other valuables when visiting casinos late at night"]},{"k":"h","s":["Laws and cultural differences"]},{"k":"hs","s":["Safeguarding National Security Law"]},{"k":"p","s":["You could face criminal charges if you take part in activities that the authorities believe threaten national security. This includes activities in and outside the Macao SAR, including in the UK. The Safeguarding National Security Law (NSL) outlines the types of activities that are illegal, such as preparing for or carrying out treason, secession or subversion against the central government."]},{"k":"p","s":["The police have the right to access an individual’s social media and private communications to gather evidence of NSL crimes."]},{"k":"hs","s":["Illegal drugs and prison sentences"]},{"k":"p","s":["Do not become involved with drugs. Possession of drugs can lead to imprisonment."]},{"k":"hs","s":["Taking photos in secure areas"]},{"k":"p","s":["Do not take photos of military installations."]},{"k":"h","s":["Transport risks"]},{"k":"hs","s":["Road travel"]},{"k":"p","s":["If you are planning to drive in Macao, see ",["information on driving abroad","https://www.gov.uk/driving-abroad"],"."]},{"k":"p","s":["You can drive in Macao with a Hong Kong, Chinese or Portuguese driving licence."]},{"k":"p","s":["If you are using a UK driving licence, you need a ",["1949 international driving permit (IDP)","https://www.gov.uk/driving-abroad/international-driving-permit"]," as well. You cannot buy an IDP outside the UK, so get one before you travel."]},{"k":"p","s":["You will also need to ",["register to drive in Macao for more than 14 days","https://www.gov.mo/en/services/ps-1488/ps-1488a/"],"."]},{"k":"hs","s":["Car hire"]},{"k":"p","s":["Some car hire companies have additional requirements, such as at least a year of driving experience and a minimum age of 21."]},{"k":"hs","s":["Unlicensed taxis"]},{"k":"p","s":["Uber is illegal in Macao. The Macao police will take action against drivers and passengers of unlicensed taxi services, including Uber."]},{"k":"h","s":["Extreme weather and natural disasters"]},{"k":"p","s":["Find out what you can do to ",["prepare for and respond to extreme weather and natural hazards","https://www.gov.uk/guidance/tropical-cyclones"],"."]},{"k":"hs","s":["Typhoons"]},{"k":"p","s":["Typhoon season normally runs from May to November. Typhoons very occasionally hit Macao and could cause flooding and landslides. Public offices will shut down when the ‘Typhoon 8’ signal is issued. Be aware of local warning signals issued in advance and follow advice issued by the local authorities."]},{"k":"p","s":["Monitor weather updates from the ",["World Meteorological Organization","https://severeweather.wmo.int/tc/wnp/index.html"]," and the ",["Macao Meteorological and Geophysical Bureau","https://www.smg.gov.mo/en"],"."]},{"k":"h","s":["Health"]},{"k":"h","s":["Health"]},{"k":"p","s":["Before you travel check that:"]},{"k":"li","s":["your destination can provide the healthcare you may need"]},{"k":"li","s":["you have ",["appropriate travel insurance","https://www.gov.uk/guidance/foreign-travel-insurance"]," for local treatment or unexpected medical evacuation"]},{"k":"p","s":["This is particularly important if you have a health condition or are pregnant."]},{"k":"h","s":["Emergency medical number"]},{"k":"p","s":["Dial 999 and ask for an ambulance."]},{"k":"p","s":["Contact your insurance company quickly if you’re referred to a medical facility for treatment."]},{"k":"h","s":["Vaccine recommendations and health risks"]},{"k":"p","s":["At least 8 weeks before your trip:"]},{"k":"li","s":["check the latest ",["vaccine recommendations for Macao","https://travelhealthpro.org.uk/country/50/chinamacao#Vaccine_Recommendations"]]},{"k":"li","s":["see where to get vaccines and whether you have to pay on the ",["NHS travel vaccinations page","https://www.nhs.uk/conditions/travel-vaccinations/"]]},{"k":"p","s":["See ",["what health risks you’ll face in Macao","https://travelhealthpro.org.uk/country/50/chinamacao"],", including malaria and dengue fever."]},{"k":"h","s":["Medication"]},{"k":"p","s":["Prescriptions issued by UK doctors are not valid in Macao. You will need to see a local doctor to get a prescription."]},{"k":"p","s":["Read ",["best practice when travelling with medicines on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/43/medicines-abroad"],"."]},{"k":"h","s":["Healthcare in Macao"]},{"k":"p","s":["FCDO has a ",["list of medical providers in Macao","https://www.gov.uk/government/publications/macao-list-of-medical-facilities"]," where some staff will speak English."]},{"k":"h","s":["Travel and mental health"]},{"k":"p","s":["Read ",["FCDO guidance on travel and mental health","https://www.gov.uk/guidance/foreign-travel-advice-for-people-with-mental-health-issues"],". There is also ",["mental health guidance on TravelHealthPro","https://travelhealthpro.org.uk/factsheet/85/travelling-with-mental-health-conditions"],"."]},{"k":"h","s":["Getting help"]},{"k":"p","s":["The Foreign, Commonwealth & Development Office (FCDO) cannot provide tailored advice for individual trips. Read this travel advice and carry out your own research before deciding whether to travel."]},{"k":"h","s":["Emergency services in Macao"]},{"k":"p","s":["Telephone: 999 (ambulance, fire, police)"]},{"k":"h","s":["Contact your travel provider and insurer"]},{"k":"p","s":["Contact your travel provider and your insurer if you are involved in a serious incident or emergency abroad. They will tell you if they can help and what you need to do."]},{"k":"hs","s":["Refunds and changes to travel"]},{"k":"p","s":["For refunds or changes to travel, contact your travel provider. You may also be able to make a claim through insurance. However, insurers usually require you to talk to your travel provider first."]},{"k":"p","s":["Find out more about ",["changing or cancelling travel plans","https://www.gov.uk/guidance/about-foreign-commonwealth-development-office-travel-advice#changing-or-cancelling-travel-plans"],", including:"]},{"k":"li","s":["where to get advice if you are in a dispute with a provider"]},{"k":"li","s":["how to access previous versions of travel advice to support a claim"]},{"k":"h","s":["Tourism Crisis Management Office"]},{"k":"p","s":["Contact the Macao Tourism Crisis Management Office on (853) 2833 3000 (24-hour hotline) for immediate and general tourism advice in English."]},{"k":"h","s":["Support from FCDO"]},{"k":"p","s":["FCDO has guidance on staying safe and what to do if you need help or support abroad, including:"]},{"k":"li","s":["finding English-speaking ",["lawyers","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/lawyers?country=Macao"],", ",["funeral directors","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/funeral-directors?country=Macao"]," and ",["translators and interpreters","https://find-a-professional-service-abroad.service.csd.fcdo.gov.uk/find/translators-interpreters?country=Macao"]," in Macao"]},{"k":"li","s":["dealing with a ",["death in Macao","https://www.gov.uk/government/publications/bereavement-information-for-macao/macao-bereavement-information"]]},{"k":"li","s":["being arrested or ",["imprisoned in Macao","https://www.gov.uk/government/publications/macao-prisoner-pack"]]},{"k":"li","s":["getting help if you’re a ",["victim of crime","https://www.gov.uk/guidance/victim-of-crime-abroad"]]},{"k":"li","s":["what to do if you’re ",["in hospital","https://www.gov.uk/guidance/in-hospital-abroad"]]},{"k":"li","s":["if you’re ",["affected by a crisis","https://www.gov.uk/guidance/how-to-deal-with-a-crisis-overseas"],", such as a terrorist attack"]},{"k":"h","s":["Contacting FCDO"]},{"k":"hs","s":["Help abroad"]},{"k":"p","s":["See ",["how to get help from the UK government abroad","https://www.contact.service.csd.fcdo.gov.uk/posts/macao/british-consulate-general-hong-kong"]," including in an emergency."]},{"k":"hs","s":["Help in the UK"]},{"k":"p","s":["You can call FCDO in London if you need urgent help because something has happened to a friend or relative abroad."]},{"k":"p","s":["Telephone: 020 7008 5000 (24 hours)"]},{"k":"p","s":[["Find out about call charges","https://www.gov.uk/call-charges"]]},{"k":"h","s":["Get travel advice updates"]},{"k":"p","s":["Sign up to ",["get email notifications","https://www.gov.uk/foreign-travel-advice/macao/email-signup"]," when this travel advice is updated."]},{"k":"p","s":["Follow FCDO:"]},{"k":"li","s":[["travel advice on X","https://x.com/fcdotravelgovuk"]]},{"k":"li","s":[["travel advice on Facebook","https://www.facebook.com/FCDOTravel/"]]},{"k":"h","s":["Risk information for British companies"]},{"k":"p","s":["The Overseas Business Risk service offers ",["information and advice for British companies operating in Macao","https://www.gov.uk/government/publications/overseas-business-risk-macao"]," on how to manage political, economic, and business security-related risks."]}],"chars":10355,"change":"New information about dual nationals returning to the UK (‘Entry requirements’ page)."},"https://theconversation.com/why-it-could-be-a-bad-idea-to-get-ai-to-flirt-for-you-295274":{"r":"conversation","at":"2026-11-17T16:38Z","sha":"dfa0f8d8b426f5f243debfc9172315f0bcddfdd3ecbc76b64587f438947ca5d1","read":"https://theconversation.com/why-it-could-be-a-bad-idea-to-get-ai-to-flirt-for-you-295274","bytes":178991,"x":"fulltext v1","title":"Why it could be a bad idea to get AI to flirt for you","by":[{"n":"Ten-Herng Lai","r":"Lecturer in Philosophy, University of Stirling"},{"n":"Alfred Archer","r":"Assistant Professor, School of Humanities and Digital Sciences, Tilburg University"}],"pub":"2026-10-30T12:26:58Z","mod":"","blocks":[{"k":"p","s":["You finally started an online conversation with a stranger you find attractive, yet you don’t really know what to say. They seem happy to talk, but you struggle to find the correct responses. You worry that their patience is growing thin. You pray for some guidance. Luckily, the solution could be just a few clicks away."]},{"k":"p","s":["After all, you have the power of ",["AI","https://theconversation.com/topics/artificial-intelligence-ai-90"]," at your fingertips. Why not use it to come up with something fun and interesting to say?"]},{"k":"p","s":["Yet many of us might hesitate in this scenario. Researchers have already warned of ",["“cognitive debt”","https://www.media.mit.edu/publications/your-brain-on-chatgpt/"]," – students can use AI to write excellent assignments, but then ",["fail miserably","https://cepr.org/publications/dp21577"]," in final exams because they remember nothing. No one would want to show up to a date unable to recall anything they had copied and pasted into an online conversation."]},{"k":"p","s":["Flirting online, like many other emotionally loaded tasks such as writing an apology, a eulogy or a message of congratulations, reflects how you feel about the person. The philosopher ",["Talbot Brewer","https://academic.oup.com/book/34596/chapter/294250266"]," wrote that a person’s efforts to make sense of their emotions through articulating them can reveal what they value."]},{"k":"p","s":["For example, suppose someone thought she didn’t especially care about her work. But then she found herself feeling pride when she was promoted. Her emotion may reveal to her that she does in fact care about workplace success."]},{"k":"h","s":["How your emotions reveal yourself to you"]},{"k":"p","s":["In our ",["recent research","https://link.springer.com/article/10.1007/s13347-026-01203-4"],", we contend that using AI to flirt – or for any other task where personal connection is valuable – risks bypassing those moments where emotions can reveal important self-knowledge."]},{"k":"p","s":["Perhaps in flirting online, a person may not read what their date says carefully. Instead, they might quickly copy the text into ChatGPT and then equally quickly paste the response back into the chat."]},{"k":"p","s":["Alternatively, perhaps an AI wingman is already integrated into the dating app, allowing people to simply click and send the suggested text. They don’t pay attention to what the date says, maybe overlooking potential deal-breakers, things that might be odd, or small stylistic details that would otherwise give them some pause."]},{"k":"p","s":["By outsourcing this emotional task to ChatGPT, it’s possible for a person to deprive themselves of the opportunity to really let the moments affect them. They could miss the chance to properly consider whether they would be happy to make compromises for their date. They may not even know whether they are genuinely excited about the date."]},{"k":"p","s":["Instead of slowly articulating their feelings and, in so doing, working out what they value in a relationship, they are authorising AI to say whatever might impress their date."]},{"k":"p","s":["There’s also the issue of ",["privacy","https://www.ethicaldatingonline.com/open-letter"]," – the flirty exchanges could find their way into training data. And is the AI wingman even trustworthy? It could misrepresent the person using it – and the other party might feel they’d suffered a deception. Even before AI, researchers have questioned whether lying on dating platforms ",["invalidates consent","https://doi.org/10.1086/670249"],"."]},{"k":"p","s":["At the end of the day, it just feels a bit disrespectful. The output of AI has little to do with how someone feels about their date, but ",["draws more from the training data","https://doi.org/10.1093/pq/pqag043"],". This data has nothing to do with the person or their date."]},{"k":"p","s":["But maybe some people are less careless. Plenty of daters would make sure to scrutinise the AI output before sending it."]},{"k":"p","s":["Yet humans have a tendency to overly trust AI. ",["Another study","https://link.springer.com/article/10.1007/s13347-025-00932-2"]," found that when people regularly let AI produce their first draft, they tend to accept the output uncritically. The study also found that people can easily adopt the biases of large language models (LLMs), even if they know those biases exist."]},{"k":"p","s":["From our own study, one worry that emerged was that instead of being true to their own feelings, over-reliance on AI may give the LLMs too much say in shaping what a person values."]},{"k":"p","s":["We are not suggesting that people should never outsource emotional tasks to AI. Sometimes, there’s no other option but to interact with emotionally manipulative or difficult people – perhaps a relative or an ex-partner. If you are already certain about your feelings towards this person, it may be better to refuse to let them ",["get to you","https://www.theatlantic.com/family/2026/10/ai-family-text/688962/"],". AI may provide some breathing space."]},{"k":"p","s":["But if as humans we want to get to know other people, have or repair meaningful relations, or make sure that what we communicate truly reflects how we feel, we should consider resisting the temptation to outsource our emotions to AI. After all, our emotions have the power to reveal to us what we deeply value."]}],"chars":4471},"https://theconversation.com/thomas-markle-allegations-undo-years-of-media-attacks-painting-meghan-as-cold-and-callous-295333":{"r":"conversation","at":"2026-11-17T16:38Z","sha":"2aa984a8cfebda3a00fdb68b2616b3c4588121453b004cb1d22626f173fd3df0","read":"https://theconversation.com/thomas-markle-allegations-undo-years-of-media-attacks-painting-meghan-as-cold-and-callous-295333","bytes":189105,"x":"fulltext v1","title":"Thomas Markle allegations undo years of media attacks painting Meghan as cold and callous","by":[{"n":"Tiara Sukhan","r":"Assistant Professor, Faculty of Information & Media Studies, Western University"}],"pub":"2026-11-03T15:51:01Z","mod":"","blocks":[{"k":"p","s":["For years, British tabloid coverage invited readers to understand Meghan Markle’s estrangement from her father as yet another chapter in the ",["Meghan Markle saga","https://doi.org/10.1080/07491409.2021.1912516"],"."]},{"k":"p","s":["Shame on the ",["uncaring daughter","https://www.news.com.au/entertainment/celebrity-life/royals/meghan-markle-slammed-for-dad-book-when-shes-estranged-from-her-own/news-story/060c4677f2491bead5dc0082eec334c0"]," who had abandoned her aging father and denied him access to his grandchildren. Meghan, the Duchess of Sussex, offered no explanation for the estrangement, leaving a gap for the media to fill with endless supposition and speculation."]},{"k":"p","s":["Now, however, readers are privy to both ",["facts and allegations that push back","https://www.theguardian.com/uk-news/2026/oct/23/thomas-markle-sr-allegations-challenge-media-meghan-narrative?"]," on the narrative long established by publications like the Mirror, The Sun and the Daily Mail, the newspaper whose reporter, Caroline Graham, ",["developed a close, longstanding friendship with Thomas Markle","https://www.bbc.com/news/articles/cy47089ql14o"]," while writing frequently on his estrangement from his daughter."]},{"k":"p","s":["We now know that in ",["2019, British police gave the duchess a letter containing allegations","https://www.theguardian.com/uk-news/2026/oct/30/iopc-watchdog-investigate-met-police-meghan-warning-letter"]," about her father."]},{"k":"p","s":["Meghan says that at the time, she had believed authorities were investigating the claims and that she ",["was told not to go public with them","https://people.com/meghan-markle-told-by-uk-police-not-to-speak-about-allegations-against-dad-thomas-markle-detailed-2019-letter-report-12206888"]," due to the potential legal implications. In her statement, she said her decision to keep her father away from her children ",["was about protecting them more than punishing him","https://globalnews.ca/news/12118338/meghan-markle-deeply-distressed-child-sex-abuse-image-claims-against-dad-thomas-markle/"],"."]},{"k":"p","s":["The allegations of Thomas Markle’s criminal behaviour do not just ask us to reconsider Meghan’s actions. They ask us to reconsider the ",["media narrative","https://theconversation.com/whats-fuelling-the-medias-enduring-hate-campaign-against-meghan-markle-239906"]," through which we understood them."]},{"k":"h","s":["Thomas Markle’s media attacks"]},{"k":"p","s":["Thomas Markle has been a recurring media presence since Prince Harry and Meghan’s 2018 wedding. His estrangement from his daughter quickly became a tabloid staple as he made himself readily available to media outlets, ",["and was reportedly paid to do so","https://www.news.com.au/entertainment/celebrity-life/royals/thomas-markle-was-paid-for-his-tellall-interview/news-story/c1de54f6c5b2b5fb2bab4448ef5911ae"]," — itself an ethical violation for most reputable news organizations."]},{"k":"p","s":["He gave interviews and ",["expressed how hurt he felt","https://www.dailymail.com/news/article-12030517/Meghan-teenage-homecoming-queen-Unseen-footage-duchess-shared-estranged-family.html"],". He talked about ",["not meeting his grandchildren","https://www.dailymail.com/news/article-12530379/Meghan-Markles-father-Thomas-Markle-wants-reconciliation.html"],". He supplied an ongoing story for a ravenous public already primed to take his side."]},{"k":"p","s":["Had the media prioritized journalistic objectivity and ethics, it should have become a problem that Thomas Markle would talk when Meghan would not."]},{"k":"p","s":["But withheld information does not stop a celebrity narrative; it just becomes part of the story."]},{"k":"p","s":["A clear informational asymmetry developed as the duchess’s apparent motivations were constructed on the basis of her silence in the face of her father’s verbosity. It should also be noted here that Prince Harry successfully launched a privacy lawsuit against the Mirror group of newspapers, settled with The Sun and lost against The Daily Mail — three news outlets that are among his wife’s harshest and most relentless critics."]},{"k":"p","s":["The British media didn’t simply report dispassionately on a family conflict between Thomas Markle and his daughter; it served up an unbalanced version of the conflict that many readers ate up."]},{"k":"p","s":["Meghan’s failure to reconcile was interpreted as callousness. Her unwillingness to explain herself was portrayed as evidence of an unappealing aloofness. Keeping her children from their grandfather was presented as proof of how vindictive or status-obsessed she was."]},{"k":"p","s":["This is of course also a narrative dependent upon culturally recognizable expectations about daughters, who are supposed to perform care, forgiveness, reconciliation and family obligation. Meghan’s refusal to behave as a dutiful daughter demanded an explanation, which ",["media commentators were happy to supply","https://www.theguardian.com/lifeandstyle/2018/dec/17/its-no-surprise-thomas-markle-and-his-daughter-meghan-are-now-estranged"],"."]},{"k":"p","s":["The now-public allegations about Thomas Markle reveal how precarious those explanations always were, particularly given the nature of the personal relationship between Thomas Markle and Graham, the Daily Mail‘s embedded reporter. This makes the usual distinction between reporting a story and participating in its construction increasingly difficult to sustain."]},{"k":"h","s":["Embedded reporter"]},{"k":"p","s":["When Thomas Markle was hospitalized in 2025, ",["Meghan’s spokesperson cited the constant presence","https://news.sky.com/story/meghan-contacts-estranged-father-thomas-markle-in-philippines-hospital-13481717?"]," of Graham at his bedside as a barrier that made private contact with him virtually impossible."]},{"k":"p","s":[["DMG Media responded","https://www.independent.co.uk/news/uk/home-news/meghan-markle-letter-estranged-father-hospital-b2881740.html"]," that Graham had had a “close relationship” with Thomas Markle since 2018, that Markle had asked her to come to his bedside and that she didn’t report on anything without his consent."]},{"k":"p","s":["But this acknowledged closeness raises an important question. At what point does sustained access become participation in the family drama being reported?"]},{"k":"p","s":["Previously the Mail on Sunday ",["published Meghan’s private letter to her father, leading her to successfully sue the publication","https://doi.org/10.1177/09564748221083129"],". There is a pattern evident in the Mail’s behaviour as private communications between father and daughter repeatedly became public media content."]},{"k":"p","s":["These are familiar issues for the British media. The ",["Leveson Inquiry (2011-12)","https://www.gov.uk/government/publications/leveson-inquiry-report-into-the-culture-practices-and-ethics-of-the-press"]," was established to investigate the culture, practices and ethics of the U.K. media after the ",["phone-hacking scandal","https://www.cnn.com/2013/10/24/world/europe/uk-phone-hacking-scandal-fast-facts"],". More than a decade later, the Thomas Markle story suggests that questions about the relationship between access, intrusion and public interest have hardly disappeared."]},{"k":"p","s":["Leveson was of course not the first time the media came under close scrutiny. The public outrage after the ",["death of Princess Diana","https://doi.org/10.1177/030981689806400104"]," in 1997 was largely directed at the photographers who were chasing her into a Paris tunnel that night and ",["the tabloid outlets that employed them","https://doi.org/10.1177/107769900308000311"],"."]},{"k":"p","s":["This prompted the industry’s self-regulatory body, the now-defunct Press Complaints Commission, to tighten its code of practice regarding harassment and privacy. Yet ultimately this regulatory framework failed to curb intrusive behaviour."]},{"k":"h","s":["The role of social media"]},{"k":"p","s":["For nearly 10 years, the media has been deploying aggressive tactics against the Duchess of Sussex that ",["mirror the harassment","https://www.theguardian.com/commentisfree/2021/mar/08/harry-meghan-oprah-winfrey-royal-british-"]," faced by her late mother-in-law. But two key factors differentiate the experiences of these two women who both married into the Royal Family — cultural subtext and the rise of social media."]},{"k":"p","s":["Coverage of Meghan has frequently employed coded tropes that target ",["her identity","https://doi.org/10.1080/14680777.2021.1928258"]," as a ",["biracial","https://pressgazette.co.uk/publishers/survey-funds-media-coverage-of-meghan-markle-racist/"],", divorced American woman. This coverage is also amplified by social media algorithms."]},{"k":"p","s":["The comment sections that accompany online stories help create an echo chamber of hostility, highly receptive to the ongoing narrative of the callous daughter and her long-suffering father."]},{"k":"p","s":["Read more: ",["Doreen Lawrence and Prince Harry’s lawsuit against Daily Mail publisher underlines need for Leveson Inquiry part two","https://theconversation.com/doreen-lawrence-and-prince-harrys-lawsuit-against-daily-mail-publisher-underlines-need-for-leveson-inquiry-part-two-192753"]]},{"k":"p","s":["The Thomas Markle revelations matter, not simply because they potentially change what we know about Meghan’s estrangement from her father. They expose how the British media turned that estrangement into a serialized narrative in which Meghan’s silence was used against her."]},{"k":"p","s":["Whether this case warrants a ",["renewed Leveson inquiry","https://www.theguardian.com/media/2018/mar/01/leveson-2-explained-what-was-it-meant-to-achieve"]," is ultimately a policy question. But it demonstrates why the ",["questions Leveson asked","https://doi.org/10.1177/1464884912443495"]," remain unresolved."]},{"k":"p","s":["The problem is not just about the degree to which the media may have demonized Meghan. It’s about how confidently it framed a story when one of its central figures could not tell her side until recently."]}],"chars":6874}};
